/* Kor hybrid-school spells — Phantomancy, Ruinmancy, Truthmancy, Alkhemancy, Dreamomancy,
   Sigilmancy and Wardamancy. Loaded after spells.js; adds to its data. Generated, not hand-edited. */
(function () {
  var D = window.SPELLDATA;
  D.books.kor = {"t": "Kor Hybrid Schools", "s": "Kor homebrew — hybrid school spells"};
  var G = {"Sigilmancy": {"d": "House Hrannmark's school of brush-and-ink spellwork, from Drevornmere. A Sigilmancy spell counts as an Evocation, Abjuration and Divination spell for any rule that cares about school.", "rules": [{"n": "Glyphs", "d": "Every Sigilmancy spell, cantrips included, has one glyph. Evocation: Snow (gentle) and Frost (harsh). Abjuration: Seal (gentle) and Unleash (harsh). Divination: Paradise (gentle) and Ruin (harsh)."}, {"n": "Script", "d": "You keep a Script, an ordered list of up to three glyphs. When you cast a Sigilmancy spell, it writes its glyph at the end of your Script after the spell takes effect. If the Script already has three glyphs, the oldest one is erased. A countered spell writes nothing. Your Script ends if you go 1 minute without writing a glyph, if you have the Incapacitated condition, or when you finish a Long Rest."}, {"n": "Sequence", "d": "A spell with a Sequence line reads the last glyph in your Script as you begin to cast it, before the spell writes its own glyph. A Sequence line can name a specific glyph, a school (\"an Evocation glyph\") or a tier (\"a gentle glyph\"). If your Script is empty, the spell has no Sequence effect."}, {"n": "Script-reading spells", "d": "A few high-level spells say they read your whole Script. They count glyphs, or check which schools are present, among all the glyphs in your Script before the spell writes its own. The Sequence line still reads only the last glyph unless the spell says otherwise."}, {"n": "Brush and ink", "d": "A calligraphy brush and ink are a Spellcasting Focus for Sigilmancy spells. Ink is consumed only when a spell's text says so."}, {"n": "Reading a sigil", "d": "A creature can take the Study action to read a sigil or ink mark left by a Sigilmancy spell (Intelligence (Arcana) check against your spell save DC). On a success, it learns the glyph and the spell's effect."}, {"n": "Writs", "d": "Some Sigilmancy spells are Writs, which are Ritual spells you inscribe with up to three glyphs in an order you choose. A Writ doesn't write to your Script. You inscribe three glyphs in an order of your choice, and repeats are allowed. The first glyph's school sets the trigger, the middle glyph's tier sets the strength, and the last glyph's school sets the result. Each Writ lists its own options."}]}, "Wardamancy": {"d": "The school of the Verithane Conservatory's wardsmiths in Revoshard: wards set on objects, and buffs that grow with the number of people working toward the same aim. A Wardamancy spell counts as an Abjuration, Transmutation and Enchantment spell for any rule that cares about school.", "rules": [{"n": "Anchor", "d": "An Anchored spell is set on an object when you cast it. The object can be one you touch or one you can see within range, and it can't be worn or carried by an unwilling creature. The spell's area originates from the Anchor and moves with it. The spell ends if the Anchor is destroyed. A willing creature can carry an Anchor, such as a standard-bearer. You can have a number of Anchors in place equal to your Proficiency Bonus. Setting one beyond that ends your oldest. A scrap of cloth, metal or stone serves as the Spellcasting Focus and as the Anchor."}, {"n": "Goal", "d": "A spell with a Unity line requires you to state a Goal aloud when you cast it: one sentence naming something the group is trying to do, such as \"Hold the bridge until dawn.\" The DM must agree that the Goal is clear and can actually be attempted."}, {"n": "Unity", "d": "Unity is the number of creatures, you included, that are willing and working toward the Goal. For an Anchored spell, count creatures in its area. For any other spell, count creatures within 30 feet of you. A creature doesn't count while it has the Charmed condition, is acting under compulsion, or is acting against the Goal (the DM decides). It counts again once it stops. Unity can't exceed twice your Proficiency Bonus. Unity is counted when you cast the spell, and again at the start of each of your turns if the spell lasts up to 1 minute. A longer spell isn't recounted. A Unity line states what changes at a given Unity."}, {"n": "Counted creature", "d": "In a spell's text, a counted creature is one that is part of Unity."}]}};
  Object.keys(G).forEach(function (k) { D.groups[k] = G[k]; });
  var S = [{"k":"kor-deathrattle","n":"Death Rattle","l":1,"s":"Phantomancy","sa":"PHA","sp":["Necromancy","Illusion"],"c":["Bard","Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Reaction, which you take when a creature you can see within 60 feet dies","rg":"60 feet","cp":"V, S","d":"Instantaneous","b":[["p","The dead creature's last breath rises as a pale apparition of its final moments. Each creature of your choice within 30 feet of the dead creature makes a Wisdom saving throw. On a failed save, a target has the Frightened condition until the end of your next turn. A creature that can't see the dead creature's space is unaffected."]],"h":[["p","The radius increases by 10 feet for each spell slot level above 1."]]},{"k":"kor-lastcandle","n":"Last Candle","l":1,"s":"Phantomancy","sa":"PHA","sp":["Necromancy","Illusion"],"c":["Bard","Cleric","Sorcerer","Wizard"],"bk":"kor","ct":"Action or Ritual","rg":"Self","cp":"V, S, M (a stub of tallow candle)","d":"Concentration, up to 1 hour","b":[["p","A pale flame hovers above your palm and sheds Dim Light in a 10-foot radius. The flame leans toward the nearest Bloodied creature within 60 feet of you other than yourself, and it burns upright when there is none."],["p","While the flame leans, you know the direction and distance to that creature and whether it is a Construct or an Undead. An illusion can't hide a Bloodied creature from the flame."]],"con":1,"rit":1},{"k":"kor-reachinghand","n":"Reaching Hand","l":1,"s":"Phantomancy","sa":"PHA","sp":["Necromancy","Illusion"],"c":["Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"60 feet","cp":"V, S","d":"Instantaneous","b":[["p","A pale hand reaches out of the air and into a creature you can see within range. Make a ranged spell attack against the target. On a hit, the target takes 3d6 Necrotic damage and can't regain Hit Points until the start of your next turn. The hand is visible to every creature that can see the target."]],"h":[["p","The damage increases by 1d6 for each spell slot level above 1."]]},{"k":"kor-phantomwound","n":"Phantom Wound","l":2,"s":"Phantomancy","sa":"PHA","sp":["Necromancy","Illusion"],"c":["Bard","Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"60 feet","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","You trace a wound in the air, and a matching one opens on a creature you can see within range. The target makes a Wisdom saving throw. On a failed save, an illusory wound appears on its body, and its body obeys what the wound claims. For the duration, the target takes 1d8 Necrotic damage at the start of each of its turns and can't regain Hit Points. Every creature that can see the target can see the wound."],["p","The target or a creature within 5 feet of it can take the Study action to make an Intelligence (Investigation) check against your spell save DC. On a success, the spell ends."]],"h":[["p","The damage increases by 1d8 for each spell slot level above 2."]],"con":1},{"k":"kor-pallidmist","n":"Pallid Mist","l":2,"s":"Phantomancy","sa":"PHA","sp":["Necromancy","Illusion"],"c":["Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"90 feet","cp":"V, S, M (a lock of grey hair)","d":"Concentration, up to 1 minute","b":[["p","You raise a 15-foot-radius Sphere of pale mist centered on a point within range, in which half-seen faces drift and sigh. The Sphere spreads around corners, and its area is Lightly Obscured. When a creature enters the Sphere for the first time on a turn or starts its turn there, it makes a Wisdom saving throw, taking 2d6 Necrotic damage on a failed save or half as much damage on a successful one."],["p","A creature can take the Study action to make an Intelligence (Investigation) check against your spell save DC. On a success, it sees the faces for what they are and has Advantage on saving throws against this spell for the duration."]],"h":[["p","The damage increases by 1d6 for each spell slot level above 2."]],"con":1},{"k":"kor-spentself","n":"Spent Self","l":2,"s":"Phantomancy","sa":"PHA","sp":["Necromancy","Illusion"],"c":["Bard","Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"Self","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","You spend part of your life to leave a copy of yourself behind. You take 2d6 Necrotic damage that can't be reduced in any way, and an illusory double of you appears in an unoccupied space within 30 feet of you. The double has AC 12 and Hit Points equal to twice the damage you took, and it mimics your movements."],["p","While the double is within 30 feet of you, roll a d6 whenever a creature makes an attack roll against you. On a 1 to 3, the attack roll targets the double instead. The spell ends when the double is reduced to 0 Hit Points."],["p","A creature can take the Study action to make an Intelligence (Investigation) check against your spell save DC. On a success, that creature ignores the double for the rest of the spell's duration."]],"h":[["p","The damage you take increases by 1d6 for each spell slot level above 2."]],"con":1},{"k":"kor-borrowedpulse","n":"Borrowed Pulse","l":3,"s":"Phantomancy","sa":"PHA","sp":["Necromancy","Illusion"],"c":["Bard","Cleric","Sorcerer","Wizard"],"bk":"kor","ct":"Action","rg":"Touch","cp":"V, S","d":"Instantaneous","b":[["p","You pass a measure of your life to another creature you touch. You take 3d8 Necrotic damage that can't be reduced in any way, and the target regains a number of Hit Points equal to the damage you took. For 1 hour afterward, an illusion masks the target's injuries, and creatures can't tell by sight that it is Bloodied."]],"h":[["p","The damage increases by 1d8 for each spell slot level above 3."]]},{"k":"kor-gravecourier","n":"Grave Courier","l":3,"s":"Phantomancy","sa":"PHA","sp":["Necromancy","Illusion"],"c":["Bard","Cleric","Warlock","Wizard"],"bk":"kor","ct":"Action or Ritual","rg":"Touch","cp":"V, S, M (a coin placed in the corpse's mouth)","d":"Instantaneous","b":[["p","You touch a corpse and speak a message of up to 25 words. The dead creature's phantom carries the message, in the voice the creature had in life, to a creature you name that is on the same plane of existence. You must have met the recipient or know both its name and a description of it."],["p","The recipient hears the message and sees the phantom standing before it for as long as the message lasts. The phantom arrives after 1 minute per 100 miles of distance, to a maximum of 24 hours. The recipient can answer with up to 25 words, which the phantom carries back to you in the same way. After it delivers the answer, the phantom dissolves."]],"rit":1},{"k":"kor-wailinghost","n":"Wailing Host","l":3,"s":"Phantomancy","sa":"PHA","sp":["Necromancy","Illusion"],"c":["Bard","Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"Self (30-foot Cone)","cp":"V, S","d":"Instantaneous","b":[["p","A chorus of pale, shrieking figures sweeps out from you in a 30-foot Cone. Each creature in the Cone makes a Wisdom saving throw. On a failed save, a creature takes 5d8 Necrotic damage and has the Frightened condition until the end of your next turn. On a successful save, a creature takes half as much damage and doesn't have the Frightened condition."]],"h":[["p","The damage increases by 1d8 for each spell slot level above 3."]]},{"k":"kor-wearthedead","n":"Wear the Dead","l":3,"s":"Phantomancy","sa":"PHA","sp":["Necromancy","Illusion"],"c":["Bard","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"Touch","cp":"V, S, M (a pinch of grave dirt)","d":"8 hours","b":[["p","You touch a Humanoid corpse that died within the last 24 hours. The corpse crumbles to ash, and for the duration you take on its appearance and voice, including the clothing and gear it wore in life. You learn its name and mannerisms, and you can ask the ashes one question as if you had cast Speak with Dead. You have Advantage on Charisma (Deception) checks made to pass as the deceased."],["p","The spell gives you none of the deceased's memories. A creature that physically inspects you can take the Study action to make an Intelligence (Investigation) check against your spell save DC, and on a success it sees through the disguise."]]},{"k":"kor-crowdofthedeparted","n":"Crowd of the Departed","l":4,"s":"Phantomancy","sa":"PHA","sp":["Necromancy","Illusion"],"c":["Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"120 feet","cp":"V, S, M (a handful of funeral ash)","d":"Concentration, up to 1 minute","b":[["p","You raise a crowd of pale apparitions in a 15-foot-radius Sphere centered on a point within range. The area is Difficult Terrain. When a creature enters the Sphere for the first time on a turn or starts its turn there, it makes a Wisdom saving throw. On a failed save, the creature takes 2d8 Necrotic damage and its Speed is halved until the start of its next turn. On a successful save, it takes half as much damage and its Speed is unchanged."],["p","A creature can take the Study action to make an Intelligence (Investigation) check against your spell save DC. On a success, it ignores the Difficult Terrain and has Advantage on saving throws against this spell for the duration."]],"h":[["p","The damage increases by 1d8 for each spell slot level above 4."]],"con":1},{"k":"kor-graveweight","n":"Grave Weight","l":4,"s":"Phantomancy","sa":"PHA","sp":["Necromancy","Illusion"],"c":["Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"60 feet","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","You convince a creature you can see within range that it is being buried alive. The target makes a Wisdom saving throw. On a failed save, it has the Restrained condition and takes 3d6 Necrotic damage at the start of each of its turns for the duration."],["p","At the end of each of its turns, the target repeats the saving throw, ending the spell on itself on a success. The target can also take the Study action to make an Intelligence (Investigation) check against your spell save DC, ending the spell on a success."]],"h":[["p","The damage increases by 1d6 for each spell slot level above 4."]],"con":1},{"k":"kor-understudyofthegrave","n":"Understudy of the Grave","l":4,"s":"Phantomancy","sa":"PHA","sp":["Necromancy","Illusion"],"c":["Bard","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"Touch","cp":"V, S, M (a coin that rested on a corpse's eyelid)","d":"8 hours","b":[["p","You touch a willing creature and leave a dead double of it waiting in the world. The first time during the duration that the target would be reduced to 0 Hit Points, it is instead reduced to 1 Hit Point, falls Prone, and has the Incapacitated condition until the end of its next turn. If an effect would kill the target instantly without dealing damage, the effect is negated instead."],["p","When this happens, the target appears to be a dead body to sight and touch for 1 minute, and the spell ends. A creature can see through the illusion by taking the Study action and succeeding on a Wisdom (Medicine) check against your spell save DC. The illusion also ends if the target takes damage or takes an action."]]},{"k":"kor-blackprocession","n":"Black Procession","l":5,"s":"Phantomancy","sa":"PHA","sp":["Necromancy","Illusion"],"c":["Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"120 feet","cp":"V, S, M (a black ribbon)","d":"Concentration, up to 1 minute","b":[["p","A procession of pale mourners files through a 15-foot-radius Sphere centered on a point within range. When you cast the spell and at the start of each of your turns, each creature in the Sphere makes a Wisdom saving throw, taking 4d8 Necrotic damage on a failed save or half as much damage on a successful one."],["p","As a Bonus Action on your turn, you can move the Sphere up to 30 feet. A creature with Truesight is unaffected."]],"h":[["p","The damage increases by 1d8 for each spell slot level above 5."]],"con":1},{"k":"kor-mirrorofthedead","n":"Mirror of the Dead","l":5,"s":"Phantomancy","sa":"PHA","sp":["Necromancy","Illusion"],"c":["Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"Self","cp":"V, S, M (a shard of dark glass)","d":"Concentration, up to 1 minute","b":[["p","A cracked mirror of dark glass hangs before you and shows the faces of the dead in place of your own. For the duration, when a creature within 5 feet of you hits you with a melee attack roll, it makes a Wisdom saving throw. On a failed save, the creature takes 3d8 Necrotic damage and has the Frightened condition until the end of your next turn. A creature with Truesight is unaffected."]],"h":[["p","The damage increases by 1d8 for each spell slot level above 5."]],"con":1},{"k":"kor-riteoffalsedeath","n":"Rite of False Death","l":5,"s":"Phantomancy","sa":"PHA","sp":["Necromancy","Illusion"],"c":["Bard","Cleric","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"30 feet","cp":"V, S, M (a pinch of grave dirt for each target)","d":"1 hour","b":[["p","Up to five willing creatures you can see within range appear dead for the duration. A target has the Incapacitated condition and appears to be a corpse to sight and touch, though its Hit Points don't change and it can still perceive its surroundings. A target can end the effect on itself (no action required)."],["p","A creature can see through the illusion by taking the Study action and succeeding on a Wisdom (Medicine) check against your spell save DC."]],"h":[["p","You can target one additional creature for each spell slot level above 5."]]},{"k":"kor-ghostlylegion","n":"Ghostly Legion","l":6,"s":"Phantomancy","sa":"PHA","sp":["Necromancy","Illusion"],"c":["Bard","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"Self","cp":"V, S, M (a handful of grave dirt)","d":"Concentration, up to 1 minute","b":[["p","You spend part of your life to raise a legion of phantom soldiers. You take 4d8 Necrotic damage that can't be reduced in any way, and four illusory soldiers appear in unoccupied spaces within 30 feet of you. Each soldier has AC 12 and 1 Hit Point, and it is destroyed when it takes any damage."],["p","A hostile creature that moves within 5 feet of a soldier for the first time on a turn makes a Wisdom saving throw. On a failed save, its Speed becomes 0 until the end of that turn. As a Bonus Action on your turn, you can move each soldier up to 30 feet to an unoccupied space within 60 feet of you."],["p","A creature can take the Study action to make an Intelligence (Investigation) check against your spell save DC. On a success, it ignores the soldiers for the rest of the spell's duration."]],"h":[["p","You raise one additional soldier for each spell slot level above 6, and you take an extra 1d8 damage."]],"con":1},{"k":"kor-hauntingverdict","n":"Haunting Verdict","l":6,"s":"Phantomancy","sa":"PHA","sp":["Necromancy","Illusion"],"c":["Bard","Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"60 feet","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","You show a creature you can see within range every wrong it has done. The target makes a Wisdom saving throw. On a failed save, it has the Frightened condition and takes 4d10 Psychic damage at the end of each of its turns for the duration."],["p","At the end of each of its turns, the target repeats the saving throw, ending the spell on itself on a success. The target can also take the Study action to make an Intelligence (Investigation) check against your spell save DC, ending the spell on a success."]],"h":[["p","The damage increases by 1d10 for each spell slot level above 6."]],"con":1},{"k":"kor-palereaping","n":"Pale Reaping","l":6,"s":"Phantomancy","sa":"PHA","sp":["Necromancy","Illusion"],"c":["Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"Self (30-foot Emanation)","cp":"V, S","d":"Instantaneous","b":[["p","A wave of pale figures pours out from you and sweeps through a 30-foot Emanation. Each creature in the Emanation other than you makes a Wisdom saving throw, taking 8d6 Necrotic damage on a failed save or half as much damage on a successful one. You gain 5 Temporary Hit Points for each creature reduced to 0 Hit Points by this spell."]],"h":[["p","The damage increases by 1d6 for each spell slot level above 6."]]},{"k":"kor-hauntofages","n":"Haunt of Ages","l":7,"s":"Phantomancy","sa":"PHA","sp":["Necromancy","Illusion"],"c":["Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"120 feet","cp":"V, S, M (a handful of dust from a battlefield)","d":"Concentration, up to 1 minute","b":[["p","You fill a 20-foot-radius, 40-foot-high Cylinder centered on a point within range with the accumulated dead of the place. When you cast the spell and at the start of each of your turns, each creature in the Cylinder makes a Wisdom saving throw, taking 4d8 Necrotic damage on a failed save or half as much damage on a successful one."],["p","A creature can take the Study action to make an Intelligence (Investigation) check against your spell save DC. On a success, it has Advantage on saving throws against this spell for the duration."]],"h":[["p","The damage increases by 1d8 for each spell slot level above 7."]],"con":1},{"k":"kor-wakingdeath","n":"Waking Death","l":7,"s":"Phantomancy","sa":"PHA","sp":["Necromancy","Illusion"],"c":["Bard","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"60 feet","cp":"V, S, M (a candle snuffed between the fingers)","d":"Concentration, up to 1 minute","b":[["p","You convince a creature you can see within range that it has just died. The target makes a Wisdom saving throw. Constructs and Undead automatically succeed. On a failed save, the target falls Prone and has the Incapacitated condition and a Speed of 0 for the duration. The spell ends early if the target takes damage."],["p","At the end of each of its turns, the target repeats the saving throw, ending the spell on itself on a success. The target can also take the Study action to make an Intelligence (Investigation) check against your spell save DC, ending the spell on a success."]],"h":[["p","You can target one additional creature for each spell slot level above 7."]],"con":1},{"k":"kor-thelastprocession","n":"The Last Procession","l":8,"s":"Phantomancy","sa":"PHA","sp":["Necromancy","Illusion"],"c":["Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"150 feet","cp":"V, S, M (a bell cast from grave goods)","d":"Concentration, up to 1 minute","b":[["p","Every person who ever died in this place walks again, in a line that fills a 40-foot-radius Sphere centered on a point within range. When you cast the spell and at the start of each of your turns, each creature of your choice in the Sphere makes a Wisdom saving throw, taking 5d8 Necrotic damage on a failed save or half as much damage on a successful one. A creature that fails also has the Frightened condition until the start of your next turn."],["p","A creature can take the Study action to make an Intelligence (Investigation) check against your spell save DC. On a success, it has Advantage on saving throws against this spell for the duration."]],"h":[["p","The damage increases by 1d8 for each spell slot level above 8."]],"con":1},{"k":"kor-unwrittenend","n":"Unwritten End","l":8,"s":"Phantomancy","sa":"PHA","sp":["Necromancy","Illusion"],"c":["Bard","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"90 feet","cp":"V, S","d":"Instantaneous","b":[["p","You strike a creature you can see within range from the record of the world. The target makes a Wisdom saving throw, taking 10d10 Necrotic damage on a failed save or half as much damage on a successful one. A creature reduced to 0 Hit Points by this spell leaves no body and no possessions behind, though magic items it carried fall to the ground."]],"h":[["p","The damage increases by 1d10 for each spell slot level above 8."]]},{"k":"kor-weakpoint","n":"Weak Point","l":1,"s":"Ruinmancy","sa":"RUI","sp":["Evocation","Divination"],"c":["Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"60 feet","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","Choose a creature you can see within range. You read where it will give way. The first time each round that a creature hits the target with an attack roll, the attack deals an extra 1d6 Force damage."]],"h":[["p","The extra damage increases by 1d6 for every two spell slot levels above 1."]],"con":1},{"k":"kor-foreseenshard","n":"Foreseen Shard","l":1,"s":"Ruinmancy","sa":"RUI","sp":["Evocation","Divination"],"c":["Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"120 feet","cp":"V, S","d":"Instantaneous","b":[["p","You glimpse where your enemies will stand and mark the spot. Choose a point you can see within range. At the start of your next turn, you can move the point up to 30 feet. A shard of unmaking then falls on it. Each creature in a 5-foot-radius Sphere centered on the point makes a Dexterity saving throw, taking 3d6 Force damage on a failed save or half as much damage on a successful one."]],"h":[["p","The damage increases by 1d6 for each spell slot level above 1."]]},{"k":"kor-stresstest","n":"Stress Test","l":1,"s":"Ruinmancy","sa":"RUI","sp":["Evocation","Divination"],"c":["Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"60 feet","cp":"V, S","d":"Instantaneous","b":[["p","Make a ranged spell attack against a creature or object within range. On a hit, the target takes 3d8 Force damage. Whether you hit or miss, you learn every Resistance, Immunity, and Vulnerability the target has."]],"h":[["p","The damage increases by 1d8 for each spell slot level above 1."]]},{"k":"kor-brittlehour","n":"Brittle Hour","l":2,"s":"Ruinmancy","sa":"RUI","sp":["Evocation","Divination"],"c":["Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"60 feet","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","Choose a creature you can see within range. It makes a Constitution saving throw. On a failed save, you choose Bludgeoning, Piercing, or Slashing damage. For the duration, the target has Vulnerability to that damage type, and it loses any Resistance or Immunity to it. The target repeats the save at the end of each of its turns, ending the effect on itself on a success."]],"con":1},{"k":"kor-hollowreport","n":"Hollow Report","l":2,"s":"Ruinmancy","sa":"RUI","sp":["Evocation","Divination"],"c":["Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"90 feet","cp":"V, S","d":"Instantaneous","b":[["p","A crack like a snapped bone runs through the air. Each creature in a 10-foot-radius Sphere centered on a point you choose within range makes a Constitution saving throw, taking 3d8 Thunder damage on a failed save or half as much damage on a successful one. A Bloodied creature has Disadvantage on the save."]],"h":[["p","The damage increases by 1d8 for each spell slot level above 2."]]},{"k":"kor-laststraw","n":"Last Straw","l":2,"s":"Ruinmancy","sa":"RUI","sp":["Evocation","Divination"],"c":["Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"60 feet","cp":"V, S","d":"Instantaneous","b":[["p","Make a ranged spell attack against a creature within range. On a hit, the target takes 4d6 Force damage, or 6d6 Force damage if it is Bloodied."]],"h":[["p","The damage increases by 1d6 for each spell slot level above 2."]]},{"k":"kor-cascadingfailure","n":"Cascading Failure","l":3,"s":"Ruinmancy","sa":"RUI","sp":["Evocation","Divination"],"c":["Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"90 feet","cp":"V, S, M (a cracked tile)","d":"Concentration, up to 1 minute","b":[["p","You read the stress in the ground and let it spread. Choose a point within range. When you cast the spell and at the start of each of your turns, each creature in a 15-foot-radius Sphere centered on that point makes a Dexterity saving throw, taking 2d6 Force damage on a failed save or half as much damage on a successful one. The damage increases by 1d6 each time it is dealt, to a maximum of 6d6."]],"h":[["p","The maximum damage increases by 1d6 for each spell slot level above 3."]],"con":1},{"k":"kor-prophesiedline","n":"Prophesied Line","l":3,"s":"Ruinmancy","sa":"RUI","sp":["Evocation","Divination"],"c":["Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"Self (100-foot Line)","cp":"V, S, M (a snapped reed)","d":"Instantaneous","b":[["p","You point down the line your enemies will take. At the start of your next turn, a 100-foot-long, 5-foot-wide Line of force originates from you in a direction you choose. Each creature in the Line makes a Dexterity saving throw, taking 9d6 Force damage on a failed save or half as much damage on a successful one."]],"h":[["p","The damage increases by 1d6 for each spell slot level above 3."]]},{"k":"kor-wallsweakness","n":"Wall's Weakness","l":3,"s":"Ruinmancy","sa":"RUI","sp":["Evocation","Divination"],"c":["Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"120 feet","cp":"V, S, M (a chip of mortar)","d":"Instantaneous","b":[["p","Choose a structure within range, such as a wall, floor, ceiling, or bridge. You learn where it is weakest, and a 10-foot Cube of it that you choose collapses into rubble. The rubble is Difficult Terrain. A creature in the Cube makes a Dexterity saving throw, taking 4d6 Bludgeoning damage on a failed save or half as much damage on a successful one."],["p","If the Cube is part of a Construct, the Construct takes 6d6 Force damage instead, with no save."]],"h":[["p","The damage increases by 1d6 for each spell slot level above 3."]]},{"k":"kor-markedhour","n":"Marked Hour","l":4,"s":"Ruinmancy","sa":"RUI","sp":["Evocation","Divination"],"c":["Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"120 feet","cp":"V, S, M (a sand timer)","d":"1 round","b":[["p","Choose a creature you can see within range. Roll 9d8 now and remember the total. At the end of the target's next turn, it makes a Constitution saving throw. It takes Force damage equal to the rolled total on a failed save or half as much damage on a successful one, wherever it is. If the target is dead when the damage would be dealt, the spell does nothing."]],"h":[["p","The damage increases by 1d8 for each spell slot level above 4."]]},{"k":"kor-seamsplitter","n":"Seam Splitter","l":4,"s":"Ruinmancy","sa":"RUI","sp":["Evocation","Divination"],"c":["Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"120 feet","cp":"V, S, M (a chisel)","d":"Instantaneous","b":[["p","You find the seam in the ground and split it. Each creature in a 15-foot-radius Sphere centered on a point within range makes a Dexterity saving throw, taking 5d8 Bludgeoning damage and gaining the Prone condition on a failed save, or taking half as much damage and no condition on a successful one. The ground in the area becomes Difficult Terrain for 1 minute."]],"h":[["p","The damage increases by 1d8 for each spell slot level above 4."]]},{"k":"kor-inevitabletremor","n":"Inevitable Tremor","l":4,"s":"Ruinmancy","sa":"RUI","sp":["Evocation","Divination"],"c":["Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"120 feet","cp":"V, S, M (a pebble from a ruin)","d":"Concentration, up to 1 minute","b":[["p","The ground in a 20-foot-radius Sphere centered on a point you choose within range begins to tremble. When you cast the spell and at the start of each of your turns, each creature in the Sphere makes a Constitution saving throw, taking 3d8 Thunder damage on a failed save or half as much damage on a successful one. At the start of each of your turns, you choose one creature in the Sphere. That creature has Disadvantage on the save."]],"h":[["p","The damage increases by 1d8 for each spell slot level above 4."]],"con":1},{"k":"kor-collapsethehorizon","n":"Collapse the Horizon","l":5,"s":"Ruinmancy","sa":"RUI","sp":["Evocation","Divination"],"c":["Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"150 feet","cp":"V, S, M (a handful of grave dust)","d":"Instantaneous","b":[["p","Everything in a 20-foot-radius Sphere centered on a point within range is shown the way it will fall. Each creature in the Sphere makes a Constitution saving throw, taking 9d8 Force damage on a failed save or half as much damage on a successful one. Constructs and unattended nonmagical objects in the Sphere take double damage."]],"h":[["p","The damage increases by 1d8 for each spell slot level above 5."]]},{"k":"kor-verdictofruin","n":"Verdict of Ruin","l":5,"s":"Ruinmancy","sa":"RUI","sp":["Evocation","Divination"],"c":["Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"60 feet","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","Choose a creature you can see within range. It makes a Wisdom saving throw. On a failed save, you pronounce its ruin. For the duration, the target loses every Resistance and Immunity to damage, and it has Vulnerability to one damage type you choose when you cast the spell. The target repeats the save at the end of each of its turns, ending the effect on itself on a success."]],"h":[["p","When you use a level 7 spell slot, the duration is 10 minutes and the target repeats the save only at the end of every third turn."]],"con":1},{"k":"kor-doomsdayreckoning","n":"Doomsday Reckoning","l":6,"s":"Ruinmancy","sa":"RUI","sp":["Evocation","Divination"],"c":["Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"120 feet","cp":"V, S, M (an hourglass cracked across)","d":"Concentration, up to 1 minute","b":[["p","When you cast the spell and at the start of each of your turns, choose a point within range. A shard of unmaking falls on that point at the start of your next turn. Each creature in a 10-foot-radius Sphere centered on the point makes a Dexterity saving throw, taking 6d8 Force damage on a failed save or half as much damage on a successful one. You can move the point up to 30 feet when the shard falls."]],"h":[["p","The damage increases by 1d8 for each spell slot level above 6."]],"con":1},{"k":"kor-rendtheseams","n":"Rend the Seams","l":6,"s":"Ruinmancy","sa":"RUI","sp":["Evocation","Divination"],"c":["Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"120 feet","cp":"V, S","d":"Instantaneous","b":[["p","You see where three creatures are most easily broken and break them. Choose up to three creatures you can see within range. Each target makes a Constitution saving throw, taking 9d8 Force damage on a failed save or half as much damage on a successful one. A target that is a Construct, or that is Bloodied, has Disadvantage on the save."]],"h":[["p","You can choose one additional creature for each spell slot level above 6."]]},{"k":"kor-ruinofthekeep","n":"Ruin of the Keep","l":7,"s":"Ruinmancy","sa":"RUI","sp":["Evocation","Divination"],"c":["Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"300 feet","cp":"V, S, M (a brick from a fallen hold)","d":"Instantaneous","b":[["p","Choose a point within range. Every structure in a 30-foot-radius Sphere centered on it that isn't magical collapses into rubble, and the rubble is Difficult Terrain. Each creature in the Sphere makes a Dexterity saving throw, taking 10d8 Bludgeoning damage on a failed save or half as much damage on a successful one."]],"h":[["p","The damage increases by 1d8 for each spell slot level above 7."]]},{"k":"kor-appointedhour","n":"Appointed Hour","l":7,"s":"Ruinmancy","sa":"RUI","sp":["Evocation","Divination"],"c":["Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"120 feet","cp":"V, S, M (a pocket watch with no hands)","d":"1 round","b":[["p","You name a creature you can see within range and the hour of its ruin. Roll 12d10 now. At the end of the target's next turn, it makes a Constitution saving throw, taking Force damage equal to the rolled total on a failed save or half as much damage on a successful one. If the target is reduced to 0 Hit Points by this spell, it dies and leaves no corpse."]],"h":[["p","The damage increases by 1d10 for each spell slot level above 7."]]},{"k":"kor-finalreckoning","n":"Final Reckoning","l":8,"s":"Ruinmancy","sa":"RUI","sp":["Evocation","Divination"],"c":["Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"120 feet","cp":"V, S, M (a scale with one pan missing)","d":"1 round","b":[["p","You read the end of every creature in a 30-foot-radius Sphere centered on a point within range and roll 16d8 now. At the start of your next turn, each creature in the Sphere makes a Constitution saving throw, taking Force damage equal to the rolled total on a failed save or half as much damage on a successful one. You can move the Sphere's center up to 30 feet before the damage is dealt."]],"h":[["p","The damage increases by 2d8 for each spell slot level above 8."]]},{"k":"kor-cascadeofendings","n":"Cascade of Endings","l":8,"s":"Ruinmancy","sa":"RUI","sp":["Evocation","Divination"],"c":["Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"150 feet","cp":"V, S, M (a shattered keystone)","d":"Concentration, up to 1 minute","b":[["p","You open a sequence of failures in a 30-foot-radius Sphere centered on a point within range. When you cast the spell and at the start of each of your turns, each creature in the Sphere makes a Constitution saving throw, taking 4d8 Force damage on a failed save or half as much damage on a successful one. The damage increases by 2d8 each time it is dealt, to a maximum of 10d8."]],"h":[["p","The maximum damage increases by 2d8 for each spell slot level above 8."]],"con":1},{"k":"kor-secondreading","n":"Second Reading","l":1,"s":"Truthmancy","sa":"TRU","sp":["Divination","Transmutation"],"c":["Bard","Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Reaction, which you take when a creature you can see within 60 feet hits with an attack roll","rg":"60 feet","cp":"V, S","d":"Instantaneous","b":[["p","You read the attack again and the true result is different. The attacker rerolls the d20 and must use the lower of the two rolls. If the new total misses, the attack misses."],["pb","Debt","The true result comes back for you. You have Disadvantage on the next D20 Test you make before the end of your next turn."]]},{"k":"kor-loadeddie","n":"Loaded Die","l":1,"s":"Truthmancy","sa":"TRU","sp":["Divination","Transmutation"],"c":["Bard","Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"60 feet","cp":"V, S, M (a die with a lead heart)","d":"Concentration, up to 1 minute","b":[["p","Choose up to two creatures you can see within range. The first time each round that a target makes a D20 Test, it rolls two d20s, and you choose which result it uses after both are rolled."],["p","When the spell ends, the true results come back for you. You have Disadvantage on the next D20 Test you make."]],"con":1},{"k":"kor-trueweight","n":"True Weight","l":1,"s":"Truthmancy","sa":"TRU","sp":["Divination","Transmutation"],"c":["Bard","Sorcerer","Wizard"],"bk":"kor","ct":"Action or Ritual","rg":"Touch","cp":"V, S, M (a pinch of lodestone)","d":"1 hour","b":[["p","Choose a creature or an object you touch. You learn its exact weight, what it is made of, and its fair market value. You can then reduce its weight to one tenth of its true weight for the duration, or restore it. A creature that is unwilling makes a Constitution saving throw to resist the weight change."]],"rit":1},{"k":"kor-fairodds","n":"Fair Odds","l":2,"s":"Truthmancy","sa":"TRU","sp":["Divination","Transmutation"],"c":["Bard","Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"30 feet","cp":"V, S, M (a marked coin)","d":"Concentration, up to 1 minute","b":[["p","Choose up to two creatures you can see within range. Each target makes a Charisma saving throw. On a failed save, you lay odds against it. For the duration, whenever the target makes an attack roll or a saving throw, it subtracts 1d6 from the roll. You learn the result of each of its saving throws before it learns it."]],"h":[["p","You can choose one additional creature for each spell slot level above 2."]],"con":1},{"k":"kor-stripthegloss","n":"Strip the Gloss","l":2,"s":"Truthmancy","sa":"TRU","sp":["Divination","Transmutation"],"c":["Bard","Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"30 feet","cp":"V, S","d":"Instantaneous","b":[["p","Choose a creature or an object you can see within range. You read what it truly is. If the target is disguised, polymorphed, or covered by an illusion that is a level 3 or lower spell, that effect ends on it. A shape-shifting creature makes a Charisma saving throw. On a failed save, it reverts to its true form and can't change shape until the end of its next turn."]]},{"k":"kor-editpoint","n":"Edit Point","l":2,"s":"Truthmancy","sa":"TRU","sp":["Divination","Transmutation"],"c":["Bard","Sorcerer","Wizard"],"bk":"kor","ct":"Action","rg":"Touch","cp":"V, S, M (a scrap of redacted vellum)","d":"1 hour","b":[["p","You touch a nonmagical object that is no larger than a 5-foot Cube. You learn what it is for, and you rewrite one of its properties. Choose one: its color or pattern, its weight (halved or doubled), its hardness (it has the AC of the next material up or down from what it is made of), or its shape (as long as its mass stays the same and it stays the same kind of object). The change lasts for the duration."]]},{"k":"kor-counterfeitdie","n":"Counterfeit Die","l":3,"s":"Truthmancy","sa":"TRU","sp":["Divination","Transmutation"],"c":["Bard","Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Reaction, which you take when a creature you can see within 60 feet makes a saving throw","rg":"60 feet","cp":"V, S","d":"Instantaneous","b":[["p","After you see the d20 roll, you change it. Increase or decrease the number rolled by up to 5 (your choice). The result can't go below 1 or above 20."],["pb","Debt","The true result comes back for you. You have Disadvantage on the next D20 Test you make before the end of your next turn."]]},{"k":"kor-redraft","n":"Redraft","l":3,"s":"Truthmancy","sa":"TRU","sp":["Divination","Transmutation"],"c":["Bard","Sorcerer","Wizard"],"bk":"kor","ct":"Action","rg":"Touch","cp":"V, S, M (a quill dipped in quicksilver)","d":"1 hour","b":[["p","You touch a nonmagical object that is no larger than a 10-foot Cube and rewrite what it is. The object becomes any other nonmagical object of the same size and approximate value that you have seen. A weapon can become another weapon, a key can become another key, and a door can become a stretch of ordinary wall. The object can't become a creature or a magic item. When the spell ends, the object reverts."]]},{"k":"kor-riggedtable","n":"Rigged Table","l":3,"s":"Truthmancy","sa":"TRU","sp":["Divination","Transmutation"],"c":["Bard","Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"60 feet","cp":"V, S, M (a loaded die)","d":"Concentration, up to 1 minute","b":[["p","Choose up to two creatures you can see within range. For the duration, a target treats any d20 roll of 9 or lower as a 10 when it makes an attack roll, an ability check, or a saving throw."],["p","When the spell ends, the true results come back for you. You have Disadvantage on the next D20 Test you make."]],"con":1},{"k":"kor-reclassify","n":"Reclassify","l":4,"s":"Truthmancy","sa":"TRU","sp":["Divination","Transmutation"],"c":["Bard","Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"60 feet","cp":"V, S, M (a catalog card)","d":"Concentration, up to 1 minute","b":[["p","Choose a creature you can see within range. You read its true nature and learn its creature type. It makes a Charisma saving throw. On a failed save, you rewrite its type to another type of your choice for the duration. Effects that depend on a creature's type, such as Hold Person, Banishment, or a Ranger's favored enemy, treat the target as its new type. The target repeats the save at the end of each of its turns, ending the effect on itself on a success."]],"con":1},{"k":"kor-setthedie","n":"Set the Die","l":4,"s":"Truthmancy","sa":"TRU","sp":["Divination","Transmutation"],"c":["Bard","Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Reaction, which you take when a creature you can see within 60 feet makes a D20 Test","rg":"60 feet","cp":"V, S","d":"Instantaneous","b":[["p","You declare the result of a roll. Choose any number from 1 to 20. The d20 roll is that number instead of what was rolled."],["pb","Debt","You have Disadvantage on every D20 Test you make until the end of your next turn."]]},{"k":"kor-fixedpoint","n":"Fixed Point","l":4,"s":"Truthmancy","sa":"TRU","sp":["Divination","Transmutation"],"c":["Bard","Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"Touch","cp":"V, S, M (a bronze nail)","d":"8 hours","b":[["p","You read a willing creature's true form and fix it in place. For the duration, the target can't have its form, size, or shape changed against its will. Spells such as Polymorph, Flesh to Stone, or Enlarge/Reduce, or a curse that alters its body fail against it, and it can't be aged or turned to stone. The target can still choose to change shape."]]},{"k":"kor-stackeddeck","n":"Stacked Deck","l":5,"s":"Truthmancy","sa":"TRU","sp":["Divination","Transmutation"],"c":["Bard","Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"Self","cp":"V, S, M (a deck of cards, which the spell burns)","d":"Concentration, up to 1 minute","b":[["p","You draw from the order of events. Roll two d20s and record the numbers, which are your Draws. Whenever a creature you can see within 60 feet makes a D20 Test, you can take a Reaction to replace the d20 roll with one of your unused Draws. Each Draw is used once. Any unused Draw is lost when the spell ends."],["pb","Debt","Each time you use a Draw, you have Disadvantage on the next D20 Test you make."]],"con":1},{"k":"kor-convertthefield","n":"Convert the Field","l":5,"s":"Truthmancy","sa":"TRU","sp":["Divination","Transmutation"],"c":["Bard","Sorcerer","Wizard"],"bk":"kor","ct":"Action","rg":"120 feet","cp":"V, S, M (a sample of each terrain)","d":"1 hour","b":[["p","You read the ground in a 30-foot-radius Sphere centered on a point within range and learn what lies beneath it, including hidden hollows, traps, and water. You then convert one kind of terrain in the Sphere into another. Mud, sand, ice, grass, loose stone, and shallow water can all become one another. The change lasts for the duration. Creatures in the area when it changes make a Dexterity saving throw or have the Prone condition, if the new terrain is slippery or unstable."]]},{"k":"kor-reversal","n":"Reversal","l":6,"s":"Truthmancy","sa":"TRU","sp":["Divination","Transmutation"],"c":["Bard","Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Reaction, which you take when a creature you can see within 60 feet takes damage or fails a saving throw","rg":"60 feet","cp":"V, S","d":"Instantaneous","b":[["p","You rewrite the last second. If the creature took damage, it takes none from that source. If it failed a saving throw, it succeeded on it instead. Any other effects of the damage or save are undone."],["pb","Debt","You have Disadvantage on every D20 Test you make until the end of your next turn."]]},{"k":"kor-striptotruth","n":"Strip to Truth","l":6,"s":"Truthmancy","sa":"TRU","sp":["Divination","Transmutation"],"c":["Bard","Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"60 feet","cp":"V, S, M (a scrap of unbleached linen)","d":"Concentration, up to 1 minute","b":[["p","Choose a creature you can see within range. You read what it truly is and learn its true form, its creature type, and whether it is under the effect of any spell. It makes a Charisma saving throw. On a failed save, every spell of level 5 or lower that is changing its shape, appearance, or abilities ends on it, and for the duration it can't benefit from such effects. It repeats the save at the end of each of its turns, ending the effect on itself on a success."]],"con":1},{"k":"kor-illstarred","n":"Ill-Starred","l":7,"s":"Truthmancy","sa":"TRU","sp":["Divination","Transmutation"],"c":["Bard","Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"120 feet","cp":"V, S, M (a black die)","d":"Concentration, up to 1 minute","b":[["p","Choose up to three creatures you can see within range. Each target makes a Charisma saving throw. On a failed save, you read its fortune and find it bad. For the duration, the target rolls every D20 Test with Disadvantage. A target repeats the save at the end of each of its turns, ending the effect on itself on a success."]],"con":1},{"k":"kor-revert","n":"Revert","l":7,"s":"Truthmancy","sa":"TRU","sp":["Divination","Transmutation"],"c":["Bard","Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"60 feet","cp":"V, S, M (a clock spring)","d":"Instantaneous","b":[["p","You rewrite a creature back to how it was. Choose a willing creature you can see within range. It returns to the state it was in at the end of the previous round: its Hit Points, its conditions, and its position. It doesn't regain spent spell slots or other expended resources, and any creature that died since then isn't restored."],["pb","Debt","You have Disadvantage on every D20 Test you make until the end of your next turn."]]},{"k":"kor-foreclosedoutcome","n":"Foreclosed Outcome","l":8,"s":"Truthmancy","sa":"TRU","sp":["Divination","Transmutation"],"c":["Bard","Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"120 feet","cp":"V, S, M (a signed and sealed contract)","d":"1 minute","b":[["p","Choose a creature you can see within range. It makes a Charisma saving throw. On a failed save, you declare its fate. The next saving throw the target makes before the spell ends is a failure, and the target can't use any feature to turn that failure into a success. A creature with Legendary Resistance that fails this save uses a use of it to succeed as normal."],["pb","Debt","You have Disadvantage on every D20 Test you make until the end of your next turn."]]},{"k":"kor-drawtheending","n":"Draw the Ending","l":8,"s":"Truthmancy","sa":"TRU","sp":["Divination","Transmutation"],"c":["Bard","Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"Self","cp":"V, S, M (a deck of cards, which the spell burns)","d":"Concentration, up to 1 minute","b":[["p","Roll four d20s and record the numbers, which are your Draws. Whenever a creature you can see within 60 feet makes a D20 Test, you can take a Reaction to replace the d20 roll with one of your unused Draws. Each Draw is used once. When the spell ends, any unused Draw is lost, and you have Disadvantage on every D20 Test you make for 1 minute."]],"con":1},{"k":"kor-sourdraught","n":"Sour Draught","l":1,"s":"Alkhemancy","sa":"ALK","sp":["Transmutation","Enchantment"],"c":["Bard","Druid","Sorcerer","Wizard"],"bk":"kor","ct":"Action","rg":"30 feet","cp":"V, S, M (a drop of vinegar)","d":"Instantaneous","b":[["p","Choose a creature you can see within range. It makes a Constitution saving throw, taking 2d8 Poison damage on a failed save or half as much damage on a successful one. On a failed save, its Speed is also reduced by 10 feet until the end of its next turn."]],"h":[["p","The damage increases by 1d8 for each spell slot level above 1."]]},{"k":"kor-tonicofcourage","n":"Tonic of Courage","l":1,"s":"Alkhemancy","sa":"ALK","sp":["Transmutation","Enchantment"],"c":["Bard","Druid","Sorcerer","Wizard"],"bk":"kor","ct":"Bonus Action","rg":"30 feet","cp":"V, S, M (a vial of strong spirits)","d":"1 hour","b":[["p","Choose a willing creature you can see within range. The target gains 2d6 Temporary Hit Points and has Advantage on saving throws against the Frightened condition for the duration."],["pb","Crash","When the effect ends on the creature, it has Disadvantage on D20 Tests until the end of its next turn."]],"h":[["p","The Temporary Hit Points increase by 1d6 for each spell slot level above 1."]]},{"k":"kor-honeyedtongue","n":"Honeyed Tongue","l":1,"s":"Alkhemancy","sa":"ALK","sp":["Transmutation","Enchantment"],"c":["Bard","Druid","Sorcerer","Wizard"],"bk":"kor","ct":"Action","rg":"30 feet","cp":"V, S, M (a spoonful of honey)","d":"1 hour","b":[["p","Choose a Humanoid you can see within range. It makes a Wisdom saving throw, with Advantage if you or your allies are fighting it. On a failed save, it has the Charmed condition for the duration, and it takes your voice for the voice it most wants to hear. The Charmed condition ends if you or your allies deal damage to the target. When the spell ends, the target knows it was charmed."]],"h":[["p","You can target one additional creature for each spell slot level above 1."]]},{"k":"kor-slowburn","n":"Slow Burn","l":2,"s":"Alkhemancy","sa":"ALK","sp":["Transmutation","Enchantment"],"c":["Bard","Druid","Sorcerer","Wizard"],"bk":"kor","ct":"Action","rg":"60 feet","cp":"V, S, M (a pinch of ash and a drop of venom)","d":"Concentration, up to 1 minute","b":[["p","Choose a creature you can see within range. It makes a Constitution saving throw. On a failed save, a slow poison takes hold of it. At the end of its next turn and at the end of each of its turns after that, it takes 4d8 Poison damage. The poison ends on the target early if it receives a spell or other effect that cures poison or disease."]],"h":[["p","The damage increases by 1d8 for each spell slot level above 2."]],"con":1},{"k":"kor-lethargytincture","n":"Lethargy Tincture","l":2,"s":"Alkhemancy","sa":"ALK","sp":["Transmutation","Enchantment"],"c":["Bard","Druid","Sorcerer","Wizard"],"bk":"kor","ct":"Action","rg":"60 feet","cp":"V, S, M (a drop of poppy milk)","d":"Concentration, up to 1 minute","b":[["p","Choose a creature you can see within range. It makes a Constitution saving throw. On a failed save, its Speed is halved, and it has Disadvantage on attack rolls and Dexterity saving throws for the duration. The target repeats the saving throw at the end of each of its turns, ending the effect on itself on a success."],["pb","Crash","When the effect ends on the target for any reason other than your losing Concentration, it has the Incapacitated condition until the end of its next turn."]],"con":1},{"k":"kor-brewedresolve","n":"Brewed Resolve","l":2,"s":"Alkhemancy","sa":"ALK","sp":["Transmutation","Enchantment"],"c":["Bard","Druid","Sorcerer","Wizard"],"bk":"kor","ct":"Bonus Action","rg":"30 feet","cp":"V, S, M (a sprig of rue)","d":"1 minute","b":[["p","Choose a creature you can see within range. The Charmed and Frightened conditions end on it, and for the duration it has Advantage on saving throws against them."],["pb","Crash","When the spell ends, the target has Disadvantage on the next Wisdom saving throw it makes."]]},{"k":"kor-bitterrage","n":"Bitter Rage","l":3,"s":"Alkhemancy","sa":"ALK","sp":["Transmutation","Enchantment"],"c":["Bard","Druid","Sorcerer","Wizard"],"bk":"kor","ct":"Action","rg":"90 feet","cp":"V, S, M (a drop of bile)","d":"Concentration, up to 1 minute","b":[["p","Each creature of your choice in a 15-foot-radius Sphere centered on a point within range makes a Wisdom saving throw. On a failed save, rage fills it. For the duration, on each of its turns it must use its action to make a melee attack against the nearest creature other than itself, and it moves toward that creature if it can. The effect ends on a creature early if you or one of your allies deals damage to it."]],"con":1},{"k":"kor-quickeningdose","n":"Quickening Dose","l":3,"s":"Alkhemancy","sa":"ALK","sp":["Transmutation","Enchantment"],"c":["Bard","Druid","Sorcerer","Wizard"],"bk":"kor","ct":"Bonus Action","rg":"30 feet","cp":"V, S, M (a pinch of quicksilver)","d":"Concentration, up to 1 minute","b":[["p","Choose a willing creature you can see within range. For the duration, its Speed increases by 20 feet, and it can take the Dash action as a Bonus Action."],["pb","Crash","When the spell ends, the target's Speed is 0 until the end of its next turn."]],"con":1},{"k":"kor-sweetenedair","n":"Sweetened Air","l":3,"s":"Alkhemancy","sa":"ALK","sp":["Transmutation","Enchantment"],"c":["Bard","Druid","Sorcerer","Wizard"],"bk":"kor","ct":"Action","rg":"90 feet","cp":"V, S, M (a sugar cube soaked in venom)","d":"Concentration, up to 1 minute","b":[["p","A sweet vapor fills a 15-foot-radius Sphere centered on a point within range. When a creature enters the Sphere for the first time on a turn or starts its turn there, it makes a Constitution saving throw, taking 3d6 Poison damage on a failed save or half as much damage on a successful one. On a failed save, the creature also has the Charmed condition until the start of its next turn and can't target you with attacks or harmful effects."]],"h":[["p","The damage increases by 1d6 for each spell slot level above 3."]],"con":1},{"k":"kor-philterofobedience","n":"Philter of Obedience","l":4,"s":"Alkhemancy","sa":"ALK","sp":["Transmutation","Enchantment"],"c":["Bard","Druid","Sorcerer","Wizard"],"bk":"kor","ct":"Action","rg":"30 feet","cp":"V, S, M (a sealed bottle of wine)","d":"Concentration, up to 1 minute","b":[["p","Choose a creature you can see within range. It makes a Wisdom saving throw. On a failed save, it has the Charmed condition for the duration, and on each of its turns it follows one simple command from you. It doesn't follow a command that would obviously kill it. The target repeats the saving throw at the end of each of its turns and whenever it takes damage, ending the effect on itself on a success."],["pb","Crash","When the effect ends on the target for any reason other than your losing Concentration, it has the Incapacitated condition until the end of its next turn."]],"con":1},{"k":"kor-stonebloodelixir","n":"Stoneblood Elixir","l":4,"s":"Alkhemancy","sa":"ALK","sp":["Transmutation","Enchantment"],"c":["Bard","Druid","Sorcerer","Wizard"],"bk":"kor","ct":"Action","rg":"Touch","cp":"V, S, M (a flake of marble)","d":"1 hour","b":[["p","A willing creature you touch gains 20 Temporary Hit Points, and its Speed is reduced by 10 feet. The Temporary Hit Points last for the duration."],["pb","Crash","When the Temporary Hit Points are gone, the creature has Disadvantage on D20 Tests until the end of its next turn."]],"h":[["p","The Temporary Hit Points increase by 5 for each spell slot level above 4."]]},{"k":"kor-distilledfear","n":"Distilled Fear","l":4,"s":"Alkhemancy","sa":"ALK","sp":["Transmutation","Enchantment"],"c":["Bard","Druid","Sorcerer","Wizard"],"bk":"kor","ct":"Action","rg":"60 feet","cp":"V, S, M (a tear in a vial)","d":"Concentration, up to 1 minute","b":[["p","Choose a creature you can see within range. It makes a Wisdom saving throw. On a failed save, it has the Frightened condition for the duration, with you as the source of its fear, and its fear sweats out of it as acid. At the end of each of its turns, it takes 4d8 Acid damage. The target repeats the saving throw at the end of each of its turns, ending the effect on itself on a success."]],"h":[["p","The damage increases by 1d8 for each spell slot level above 4."]],"con":1},{"k":"kor-sleepersdraught","n":"Sleeper's Draught","l":5,"s":"Alkhemancy","sa":"ALK","sp":["Transmutation","Enchantment"],"c":["Bard","Druid","Sorcerer","Wizard"],"bk":"kor","ct":"Action","rg":"90 feet","cp":"V, S, M (a pinch of poppy seed)","d":"Concentration, up to 1 minute","b":[["p","Each creature of your choice in a 20-foot-radius Sphere centered on a point within range makes a Constitution saving throw. On a failed save, a heavy dose takes hold. Onset. At the end of its next turn, the creature has the Unconscious condition for the duration. The condition ends on it if it takes damage or another creature uses an action to shake it awake."]],"con":1},{"k":"kor-bestialtonic","n":"Bestial Tonic","l":5,"s":"Alkhemancy","sa":"ALK","sp":["Transmutation","Enchantment"],"c":["Bard","Druid","Sorcerer","Wizard"],"bk":"kor","ct":"Action","rg":"Touch","cp":"V, S, M (a hair from a predator)","d":"Concentration, up to 1 minute","b":[["p","A willing creature you touch takes on the traits of a predator for the duration. Its Speed increases by 10 feet, it gains a Climb Speed equal to its Speed, and its Unarmed Strikes deal 2d6 Slashing damage and count as magical."],["pb","Crash","When the effect ends on the creature, it has Disadvantage on D20 Tests until the end of its next turn."]],"con":1},{"k":"kor-corrosivedraught","n":"Corrosive Draught","l":6,"s":"Alkhemancy","sa":"ALK","sp":["Transmutation","Enchantment"],"c":["Bard","Druid","Sorcerer","Wizard"],"bk":"kor","ct":"Action","rg":"60 feet","cp":"V, S, M (a flask of acid)","d":"Instantaneous","b":[["p","Choose a creature you can see within range. It makes a Constitution saving throw, taking 12d6 Acid damage on a failed save or half as much damage on a successful one. On a failed save, any nonmagical armor it wears takes a permanent and cumulative -1 penalty to the AC it offers, to a minimum AC of 10 with that armor."]],"h":[["p","The damage increases by 1d6 for each spell slot level above 6."]]},{"k":"kor-philterofdevotion","n":"Philter of Devotion","l":6,"s":"Alkhemancy","sa":"ALK","sp":["Transmutation","Enchantment"],"c":["Bard","Druid","Sorcerer","Wizard"],"bk":"kor","ct":"Action","rg":"30 feet","cp":"V, S, M (a lock of hair from a loved one)","d":"Concentration, up to 1 minute","b":[["p","Choose a creature you can see within range. It makes a Wisdom saving throw. On a failed save, it has the Charmed condition for the duration and regards you as the person it most trusts. On each of its turns, it takes the actions you choose for it. It repeats the saving throw at the end of each of its turns and whenever it takes damage, ending the effect on itself on a success."],["pb","Crash","When the effect ends on the target for any reason other than your losing Concentration, it has the Stunned condition until the end of its next turn."]],"con":1},{"k":"kor-transmutedhatred","n":"Transmuted Hatred","l":7,"s":"Alkhemancy","sa":"ALK","sp":["Transmutation","Enchantment"],"c":["Bard","Druid","Sorcerer","Wizard"],"bk":"kor","ct":"Action","rg":"120 feet","cp":"V, S, M (a vial of boiled bile)","d":"Concentration, up to 1 minute","b":[["p","You turn the hostility of every creature in a 20-foot-radius Sphere centered on a point within range against its own body. When you cast the spell and at the start of each of your turns, each creature in the Sphere makes a Wisdom saving throw, taking 4d8 Psychic damage on a failed save or half as much damage on a successful one."]],"h":[["p","The damage increases by 1d8 for each spell slot level above 7."]],"con":1},{"k":"kor-universalsolvent","n":"Universal Solvent","l":7,"s":"Alkhemancy","sa":"ALK","sp":["Transmutation","Enchantment"],"c":["Bard","Druid","Sorcerer","Wizard"],"bk":"kor","ct":"Action","rg":"Touch","cp":"V, S, M (a flask of quicksilver and vinegar)","d":"Instantaneous","b":[["p","Choose a nonmagical object that fits within a 10-foot Cube and that isn't being worn or carried. It dissolves into fine powder or clean liquid. If the object is part of a larger one, it leaves a hole of that size. Alternatively, you transmute the object into another nonmagical material of equal value."]]},{"k":"kor-greatsedation","n":"Great Sedation","l":8,"s":"Alkhemancy","sa":"ALK","sp":["Transmutation","Enchantment"],"c":["Bard","Druid","Sorcerer","Wizard"],"bk":"kor","ct":"Action","rg":"120 feet","cp":"V, S, M (a vial of night-blooming sap)","d":"Concentration, up to 1 minute","b":[["p","Each creature of your choice in a 20-foot-radius Sphere centered on a point within range makes a Wisdom saving throw. On a failed save, a deep dose takes hold. Onset. At the end of its next turn, the creature has the Unconscious condition for the duration. The condition ends on it if it takes damage or another creature uses an action to shake it awake."],["pb","Crash","When the condition ends on a creature, it has the Stunned condition until the end of its next turn."]],"con":1},{"k":"kor-elixirofvigor","n":"Elixir of Vigor","l":8,"s":"Alkhemancy","sa":"ALK","sp":["Transmutation","Enchantment"],"c":["Bard","Druid","Sorcerer","Wizard"],"bk":"kor","ct":"Action","rg":"Touch","cp":"V, S, M (a flask of distilled sunlight)","d":"Instantaneous","b":[["p","A willing creature you touch regains 70 Hit Points. The spell also ends the Blinded, Deafened, Paralyzed, Poisoned, and Stunned conditions on the target, and reduces its Exhaustion level by one."],["pb","Crash","The target has Disadvantage on D20 Tests until the end of its next turn."]]},{"k":"kor-dreamdouble","n":"Dream Double","l":1,"s":"Dreamomancy","sa":"DRE","sp":["Abjuration","Illusion"],"c":["Bard","Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Bonus Action","rg":"Self","cp":"V, S","d":"1 minute","b":[["p","A shimmering double of you stands where you stand. You gain 3d8 Temporary Hit Points for the duration. A creature that takes the Study action and succeeds on an Intelligence (Investigation) check against your spell save DC sees the double for what it is, and damage that creature deals to you ignores these Temporary Hit Points."]],"h":[["p","The Temporary Hit Points increase by 1d8 for each spell slot level above 1."]]},{"k":"kor-counterfeitwound","n":"Counterfeit Wound","l":2,"s":"Dreamomancy","sa":"DRE","sp":["Abjuration","Illusion"],"c":["Bard","Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Reaction, which you take when a creature you can see hits you with an attack roll","rg":"Self","cp":"V, S","d":"Instantaneous","b":[["p","A dream double takes the blow in your place. You take half the damage from the attack, rounded down. The attacker then makes a Wisdom saving throw. On a failed save, it has Disadvantage on its next attack roll before the end of its next turn."]]},{"k":"kor-dreamerspavilion","n":"Dreamer's Pavilion","l":3,"s":"Dreamomancy","sa":"DRE","sp":["Abjuration","Illusion"],"c":["Bard","Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"10 minutes or Ritual","rg":"Self (30-foot-radius Emanation)","cp":"V, S, M (a scrap of bedding)","d":"8 hours","b":[["p","A pavilion made of dream fills the area. From outside it looks like whatever ordinary thing you imagine, such as a ruined hut or a bare hill. Creatures of your choice inside the Emanation can't be targeted by Divination spells, can't be affected by Charm effects from creatures outside it, and can't be reached by the Dream or Nightmare spells. A creature of your choice that finishes a Long Rest inside it also regains all its Hit Point Dice and has its Exhaustion level reduced by one extra level."]],"rit":1},{"k":"kor-phantombodyguard","n":"Phantom Bodyguard","l":4,"s":"Dreamomancy","sa":"DRE","sp":["Abjuration","Illusion"],"c":["Bard","Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"30 feet","cp":"V, S, M (a toy soldier)","d":"Concentration, up to 1 hour","b":[["p","An illusory guardian stands in an unoccupied space you can see within range. It has AC 15, 40 Hit Points, and Immunity to Poison and Psychic damage. Each creature that starts its turn within 30 feet of the guardian and can see it makes a Wisdom saving throw. On a failed save, it must target the guardian with its attacks that turn. A creature can take the Study action to make an Intelligence (Investigation) check against your spell save DC, ending that save's effect on itself on a success. The spell ends if the guardian is reduced to 0 Hit Points."]],"h":[["p","The guardian's Hit Points increase by 10 for each spell slot level above 4."]],"con":1},{"k":"kor-lucidrest","n":"Lucid Rest","l":5,"s":"Dreamomancy","sa":"DRE","sp":["Abjuration","Illusion"],"c":["Bard","Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"1 minute or Ritual","rg":"Touch","cp":"V, S, M (a feather pillow)","d":"1 minute","b":[["p","You and up to five willing creatures you touch share a lucid dream. At the end of the minute, each of you finishes a Short Rest. A creature can benefit from this spell only once between Long Rests. While you dream, each of you is Incapacitated, and each of you can wake at any time (no action required)."]],"rit":1},{"k":"kor-dreamersbastion","n":"Dreamer's Bastion","l":6,"s":"Dreamomancy","sa":"DRE","sp":["Abjuration","Illusion"],"c":["Bard","Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"Self (30-foot Emanation)","cp":"V, S, M (a lullaby written on vellum)","d":"Concentration, up to 10 minutes","b":[["p","A bastion of dream surrounds you. For the duration, creatures of your choice in the Emanation have Resistance to Psychic damage and can't have the Charmed, Frightened, or Unconscious conditions. A creature that leaves the Emanation loses these benefits until it returns."]],"con":1},{"k":"kor-wakingmirror","n":"Waking Mirror","l":7,"s":"Dreamomancy","sa":"DRE","sp":["Abjuration","Illusion"],"c":["Bard","Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Reaction, which you take when a creature you can see within 60 feet is hit by an attack roll or fails a saving throw against an attack or spell","rg":"60 feet","cp":"V, S","d":"Instantaneous","b":[["p","A mirror of dream catches the harm and turns it back. The creature takes half the damage it would take, and the creature that caused the damage takes the other half as Psychic damage. If the damage came from a spell, that creature makes a Wisdom saving throw, taking the damage on a failed save or no damage on a successful one."]]},{"k":"kor-gentlenight","n":"Gentle Night","l":8,"s":"Dreamomancy","sa":"DRE","sp":["Abjuration","Illusion"],"c":["Bard","Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"Touch","cp":"V, S, M (a dream catcher woven with your hair)","d":"8 hours","b":[["p","A willing creature you touch is wrapped in a dream that keeps it safe. For the duration, the target is immune to the Charmed, Frightened, and Stunned conditions, and it has Advantage on saving throws against effects that would cause it to take Psychic damage or lose Hit Points. If the target is reduced to 0 Hit Points, it instead drops to 1 Hit Point and the spell ends. The spell can do this only once."]]},{"k":"kor-baddream","n":"Bad Dream","l":1,"s":"Dreamomancy","sa":"DRE","sp":["Abjuration","Illusion"],"c":["Bard","Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"60 feet","cp":"V, S","d":"Instantaneous","b":[["p","Choose a creature you can see within range. It sees the worst thing it can imagine. It makes a Wisdom saving throw, taking 2d8 Psychic damage on a failed save or half as much damage on a successful one. On a failed save, it also has the Frightened condition until the end of its next turn."]],"h":[["p","The damage increases by 1d8 for each spell slot level above 1."]]},{"k":"kor-drowse","n":"Drowse","l":1,"s":"Dreamomancy","sa":"DRE","sp":["Abjuration","Illusion"],"c":["Bard","Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"30 feet","cp":"V, S, M (a pinch of sand)","d":"Concentration, up to 1 minute","b":[["p","Choose up to two creatures you can see within range. Each makes a Wisdom saving throw. On a failed save, it has the Incapacitated condition for the duration. The condition ends early if the target takes damage. The target repeats the saving throw at the end of each of its turns, ending the effect on itself on a success. A creature that doesn't sleep, or that is immune to being Charmed, is unaffected."]],"h":[["p","You can target one additional creature for each spell slot level above 1."]],"con":1},{"k":"kor-nightmaresnare","n":"Nightmare Snare","l":2,"s":"Dreamomancy","sa":"DRE","sp":["Abjuration","Illusion"],"c":["Bard","Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"60 feet","cp":"V, S, M (a thread knotted three times)","d":"Concentration, up to 1 minute","b":[["p","Choose a creature you can see within range. It makes a Wisdom saving throw. On a failed save, chains made of its own fears hold it in place, and it has the Restrained condition for the duration. The target repeats the saving throw at the end of each of its turns, ending the effect on itself on a success. A creature can take the Study action to make an Intelligence (Investigation) check against your spell save DC, ending the effect on itself on a success."]],"con":1},{"k":"kor-dreadlullaby","n":"Dread Lullaby","l":2,"s":"Dreamomancy","sa":"DRE","sp":["Abjuration","Illusion"],"c":["Bard","Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"Self (10-foot Emanation)","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","You hum a tune that shows every listener its worst dream. Each creature of your choice in a 10-foot Emanation originating from you makes a Wisdom saving throw. On a failed save, it has the Frightened condition of you for the duration and drops whatever it is holding. The creature repeats the saving throw at the end of each of its turns, ending the effect on itself on a success."]],"con":1},{"k":"kor-pitofthefallingdream","n":"Pit of the Falling Dream","l":3,"s":"Dreamomancy","sa":"DRE","sp":["Abjuration","Illusion"],"c":["Bard","Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"90 feet","cp":"V, S, M (a feather and a lead weight)","d":"Concentration, up to 1 minute","b":[["p","Creatures in a 15-foot-radius Sphere centered on a point within range feel themselves falling forever. When the spell is cast and at the start of each of a creature's turns in the Sphere, the creature makes a Wisdom saving throw. On a failed save, it has the Prone condition and its Speed is 0 until the end of its turn."]],"con":1},{"k":"kor-wakingnightmare","n":"Waking Nightmare","l":3,"s":"Dreamomancy","sa":"DRE","sp":["Abjuration","Illusion"],"c":["Bard","Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"120 feet","cp":"V, S, M (a black candle)","d":"Concentration, up to 1 minute","b":[["p","Creatures in a 10-foot-radius Sphere centered on a point within range see their own nightmares walk toward them. When the spell is cast and at the start of each of your turns, each creature in the Sphere makes a Wisdom saving throw, taking 3d8 Psychic damage on a failed save or half as much damage on a successful one."]],"h":[["p","The damage increases by 1d8 for each spell slot level above 3."]],"con":1},{"k":"kor-nightmarecell","n":"Nightmare Cell","l":4,"s":"Dreamomancy","sa":"DRE","sp":["Abjuration","Illusion"],"c":["Bard","Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"60 feet","cp":"V, S, M (an iron key with no lock)","d":"Concentration, up to 1 minute","b":[["p","Choose a creature you can see within range. It makes a Wisdom saving throw. On a failed save, it is shut in a cell made of its worst memory. For the duration, it has the Incapacitated condition and its Speed is 0, and at the end of each of its turns it takes 2d8 Psychic damage. The target repeats the saving throw at the end of each of its turns, ending the effect on itself on a success. A creature can take the Study action to make an Intelligence (Investigation) check against your spell save DC, ending the effect on itself on a success."]],"h":[["p","The damage increases by 1d8 for each spell slot level above 4."]],"con":1},{"k":"kor-loopingcorridor","n":"Looping Corridor","l":4,"s":"Dreamomancy","sa":"DRE","sp":["Abjuration","Illusion"],"c":["Bard","Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"90 feet","cp":"V, S, M (a ball of twine)","d":"Concentration, up to 1 minute","b":[["p","A corridor that has no end opens around creatures in a 20-foot-radius Sphere centered on a point within range. Each creature in the Sphere makes a Wisdom saving throw. On a failed save, the creature can't move more than 5 feet from where it is, and every path it walks leads back. It repeats the saving throw at the end of each of its turns, ending the effect on itself on a success. A creature can take the Study action to make an Intelligence (Investigation) check against your spell save DC, ending the effect on itself on a success."]],"con":1},{"k":"kor-drowningdream","n":"Drowning Dream","l":5,"s":"Dreamomancy","sa":"DRE","sp":["Abjuration","Illusion"],"c":["Bard","Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"60 feet","cp":"V, S, M (a vial of seawater)","d":"Instantaneous","b":[["p","Choose a creature you can see within range. It sinks into a dream of drowning and makes a Wisdom saving throw, taking 7d8 Psychic damage on a failed save or half as much damage on a successful one. On a failed save, it also has the Incapacitated condition until the end of its next turn."]],"h":[["p","The damage increases by 1d8 for each spell slot level above 5."]]},{"k":"kor-neverendingnightmare","n":"Neverending Nightmare","l":6,"s":"Dreamomancy","sa":"DRE","sp":["Abjuration","Illusion"],"c":["Bard","Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"60 feet","cp":"V, S, M (a black pearl)","d":"Concentration, up to 1 minute","b":[["p","Choose a creature you can see within range. It makes a Wisdom saving throw. On a failed save, it is trapped in a nightmare that ends only when the spell does. For the duration, it has the Incapacitated condition and its Speed is 0, and at the end of each of its turns it takes 2d8 Psychic damage. The target repeats the saving throw at the end of every third turn, ending the effect on itself on a success. A creature can take the Study action to make an Intelligence (Investigation) check against your spell save DC, ending the effect on itself on a success."]],"h":[["p","The damage increases by 1d8 for each spell slot level above 6."]],"con":1},{"k":"kor-terroreclipse","n":"Terror Eclipse","l":7,"s":"Dreamomancy","sa":"DRE","sp":["Abjuration","Illusion"],"c":["Bard","Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"120 feet","cp":"V, S, M (a shard of smoked glass)","d":"Concentration, up to 1 minute","b":[["p","The light dies in a 15-foot-radius Sphere centered on a point within range, and every creature in it sees what it fears most. When the spell is cast and at the start of each of your turns, each creature in the Sphere makes a Wisdom saving throw, taking 3d8 Psychic damage on a failed save or half as much damage on a successful one. On a failed save, the creature also has the Frightened condition until the start of its next turn."]],"h":[["p","The damage increases by 1d8 for each spell slot level above 7."]],"con":1},{"k":"kor-nightmaremaze","n":"Nightmare Maze","l":8,"s":"Dreamomancy","sa":"DRE","sp":["Abjuration","Illusion"],"c":["Bard","Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"60 feet","cp":"V, S, M (a clay labyrinth)","d":"Concentration, up to 10 minutes","b":[["p","Choose a creature you can see within range. It makes a Wisdom saving throw. On a failed save, it vanishes into a labyrinth of its own nightmares and has the Incapacitated condition for the duration. At the end of each of its turns, it can make an Intelligence (Investigation) check against your spell save DC, ending the effect on itself on a success. When the effect ends, the creature reappears in the space it left, or in the nearest unoccupied space if that space is occupied."]],"con":1},{"k":"kor-foretoldwound","n":"Foretold Wound","l":0,"s":"Phantomancy","sa":"PHA","sp":["Necromancy","Illusion"],"c":["Bard","Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"60 feet","cp":"V, S","d":"1 round","b":[["p","One creature you can see within range sees the wound that is coming for it. At the end of the target's next turn, it makes a Wisdom saving throw, taking 1d10 Necrotic damage on a failed save. If the target takes the Study action on that turn, it has Advantage on the save."]],"h":[["pb","Cantrip Upgrade","The damage increases by 1d10 when you reach levels 5 (2d10), 11 (3d10), and 17 (4d10)."]]},{"k":"kor-pallbearerschill","n":"Pallbearer's Chill","l":0,"s":"Phantomancy","sa":"PHA","sp":["Necromancy","Illusion"],"c":["Bard","Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"Self (5-foot Emanation)","cp":"V, S","d":"Instantaneous","b":[["p","Cold from a grave you have never seen pours off you. Each creature of your choice in a 5-foot Emanation originating from you makes a Constitution saving throw, taking 1d6 Necrotic damage on a failed save."]],"h":[["pb","Cantrip Upgrade","The damage increases by 1d6 when you reach levels 5 (2d6), 11 (3d6), and 17 (4d6)."]]},{"k":"kor-dyingecho","n":"Dying Echo","l":0,"s":"Phantomancy","sa":"PHA","sp":["Necromancy","Illusion"],"c":["Bard","Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"60 feet","cp":"V, S","d":"1 round","b":[["p","A creature you can see within range sees its own corpse lying in front of it. The target makes a Wisdom saving throw, taking 1d6 Necrotic damage on a failed save. On a failed save, it also has Disadvantage on the next attack roll it makes before the end of its next turn."]],"h":[["pb","Cantrip Upgrade","The damage increases by 1d6 when you reach levels 5 (2d6), 11 (3d6), and 17 (4d6)."]]},{"k":"kor-corpsecandle","n":"Corpse Candle","l":0,"s":"Phantomancy","sa":"PHA","sp":["Necromancy","Illusion"],"c":["Bard","Cleric","Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"Self","cp":"V, S, M (a stub of tallow)","d":"1 hour","b":[["p","A pale flame with no heat hovers in your hand and sheds Dim Light in a 10-foot radius. While a corpse is in that light, you know how long it has been dead and what killed it. The flame ends if you cast this spell again or dismiss it (no action required)."]]},{"k":"kor-feignpallor","n":"Feign Pallor","l":0,"s":"Phantomancy","sa":"PHA","sp":["Necromancy","Illusion"],"c":["Bard","Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"Self","cp":"V, S","d":"1 hour","b":[["p","You look dead to every creature more than 5 feet away from you. A creature can see through the illusion by taking the Study action to make an Intelligence (Investigation) check against your spell save DC, or by coming within 5 feet of you. While the illusion holds, you have Advantage on Dexterity (Stealth) checks made against creatures that believe you are dead. The spell ends if you take an action other than moving or speaking."]]},{"k":"kor-faultstrike","n":"Fault Strike","l":0,"s":"Ruinmancy","sa":"RUI","sp":["Evocation","Divination"],"c":["Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"60 feet","cp":"V, S","d":"Instantaneous","b":[["p","Make a ranged spell attack against a creature or object within range. On a hit, the target takes 1d8 Force damage, or 1d12 Force damage if it is Bloodied."]],"h":[["pb","Cantrip Upgrade","The damage increases by 1d8 when you reach levels 5 (2d8), 11 (3d8), and 17 (4d8)."]]},{"k":"kor-crumble","n":"Crumble","l":0,"s":"Ruinmancy","sa":"RUI","sp":["Evocation","Divination"],"c":["Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"60 feet","cp":"V, S","d":"Instantaneous","b":[["p","Choose a creature or an object you can see within range. A creature makes a Constitution saving throw, taking 1d8 Thunder damage on a failed save. An object that isn't being worn or carried takes the damage with no save, and a Construct takes double damage."]],"h":[["pb","Cantrip Upgrade","The damage increases by 1d8 when you reach levels 5 (2d8), 11 (3d8), and 17 (4d8)."]]},{"k":"kor-appointedbruise","n":"Appointed Bruise","l":0,"s":"Ruinmancy","sa":"RUI","sp":["Evocation","Divination"],"c":["Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"60 feet","cp":"V, S","d":"1 round","b":[["p","Choose a creature you can see within range. At the end of its next turn, it takes 1d6 Force damage if it is within 120 feet of you."]],"h":[["pb","Cantrip Upgrade","The damage increases by 1d6 when you reach levels 5 (2d6), 11 (3d6), and 17 (4d6)."]]},{"k":"kor-readthecrack","n":"Read the Crack","l":0,"s":"Ruinmancy","sa":"RUI","sp":["Evocation","Divination"],"c":["Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"30 feet","cp":"V, S","d":"Instantaneous","b":[["p","Choose a structure or an object you can see within range. You learn where it is weakest and how many Hit Points it has. A creature that is a Construct gives you the same information."]]},{"k":"kor-assaywound","n":"Assay Wound","l":0,"s":"Ruinmancy","sa":"RUI","sp":["Evocation","Divination"],"c":["Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"60 feet","cp":"V, S","d":"Instantaneous","b":[["p","Choose a creature you can see within range. You learn whether it is at full Hit Points, at more than half, Bloodied, or at less than a tenth of its Hit Points."]]},{"k":"kor-loadedstrike","n":"Loaded Strike","l":0,"s":"Truthmancy","sa":"TRU","sp":["Divination","Transmutation"],"c":["Bard","Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"60 feet","cp":"V, S","d":"Instantaneous","b":[["p","Make a ranged spell attack against a creature within range. On a miss, you can make the attack roll again once with Disadvantage. On a hit, the target takes 1d6 Force damage."]],"h":[["pb","Cantrip Upgrade","The damage increases by 1d6 when you reach levels 5 (2d6), 11 (3d6), and 17 (4d6)."]]},{"k":"kor-plainsight","n":"Plain Sight","l":0,"s":"Truthmancy","sa":"TRU","sp":["Divination","Transmutation"],"c":["Bard","Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"60 feet","cp":"V, S","d":"1 round","b":[["p","Choose a creature you can see within range. It makes a Wisdom saving throw, taking 1d8 Psychic damage on a failed save. On a failed save, it also has no benefit from the Invisible condition or from illusions that disguise it until the end of its next turn."]],"h":[["pb","Cantrip Upgrade","The damage increases by 1d8 when you reach levels 5 (2d8), 11 (3d8), and 17 (4d8)."]]},{"k":"kor-deadweight","n":"Dead Weight","l":0,"s":"Truthmancy","sa":"TRU","sp":["Divination","Transmutation"],"c":["Bard","Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"60 feet","cp":"V, S","d":"1 round","b":[["p","Choose a creature you can see within range. It makes a Strength saving throw, taking 1d8 Bludgeoning damage on a failed save. On a failed save, its Speed is also reduced by 10 feet until the end of its next turn."]],"h":[["pb","Cantrip Upgrade","The damage increases by 1d8 when you reach levels 5 (2d8), 11 (3d8), and 17 (4d8)."]]},{"k":"kor-redraw","n":"Redraw","l":0,"s":"Truthmancy","sa":"TRU","sp":["Divination","Transmutation"],"c":["Bard","Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"Touch","cp":"V, S","d":"1 hour","b":[["p","You touch a nonmagical object and rewrite one small detail of it. You can change up to 25 words of writing on it, the pattern of a seal, or its color. The change lasts for the duration, and the object reverts when the spell ends."]]},{"k":"kor-faircount","n":"Fair Count","l":0,"s":"Truthmancy","sa":"TRU","sp":["Divination","Transmutation"],"c":["Bard","Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"60 feet","cp":"V, S","d":"Instantaneous","b":[["p","Choose one kind of creature or object you can see within range, such as guards, coins, or doors. You learn exactly how many there are in your line of sight."]]},{"k":"kor-bitterdrop","n":"Bitter Drop","l":0,"s":"Alkhemancy","sa":"ALK","sp":["Transmutation","Enchantment"],"c":["Bard","Druid","Sorcerer","Wizard"],"bk":"kor","ct":"Action","rg":"30 feet","cp":"V, S, M (a drop of gall)","d":"Instantaneous","b":[["p","Choose a creature you can see within range. It makes a Constitution saving throw, taking 1d10 Poison damage on a failed save."]],"h":[["pb","Cantrip Upgrade","The damage increases by 1d10 when you reach levels 5 (2d10), 11 (3d10), and 17 (4d10)."]]},{"k":"kor-slowdose","n":"Slow Dose","l":0,"s":"Alkhemancy","sa":"ALK","sp":["Transmutation","Enchantment"],"c":["Bard","Druid","Sorcerer","Wizard"],"bk":"kor","ct":"Action","rg":"30 feet","cp":"V, S, M (a drop of venom)","d":"1 round","b":[["p","Choose a creature you can see within range. It makes a Constitution saving throw. On a failed save, a dose takes hold. Onset. At the end of its next turn, it takes 2d6 Poison damage."]],"h":[["pb","Cantrip Upgrade","The damage increases by 1d6 when you reach levels 5 (3d6), 11 (4d6), and 17 (5d6)."]]},{"k":"kor-causticmist","n":"Caustic Mist","l":0,"s":"Alkhemancy","sa":"ALK","sp":["Transmutation","Enchantment"],"c":["Bard","Druid","Sorcerer","Wizard"],"bk":"kor","ct":"Action","rg":"30 feet","cp":"V, S, M (a pinch of salt)","d":"Instantaneous","b":[["p","A burst of mist forms at a point you choose within range. Each creature in a 5-foot-radius Sphere centered on that point makes a Dexterity saving throw, taking 1d6 Acid damage on a failed save."]],"h":[["pb","Cantrip Upgrade","The damage increases by 1d6 when you reach levels 5 (2d6), 11 (3d6), and 17 (4d6)."]]},{"k":"kor-distillation","n":"Distillation","l":0,"s":"Alkhemancy","sa":"ALK","sp":["Transmutation","Enchantment"],"c":["Bard","Druid","Sorcerer","Wizard"],"bk":"kor","ct":"Action","rg":"Touch","cp":"V, S, M (a clean glass)","d":"Instantaneous","b":[["p","You touch up to 1 gallon of liquid or up to 1 pound of food. You can purify it of nonmagical poison and disease, or turn it into another nonmagical liquid or food of the same quantity and similar value, such as water into wine or grain into bread."]]},{"k":"kor-soberingtouch","n":"Sobering Touch","l":0,"s":"Alkhemancy","sa":"ALK","sp":["Transmutation","Enchantment"],"c":["Bard","Druid","Sorcerer","Wizard"],"bk":"kor","ct":"Action","rg":"Touch","cp":"V, S","d":"Instantaneous","b":[["p","You touch a creature. Any nonmagical intoxication, drowsiness, or nausea in it ends. If the creature is under an effect that causes the Charmed condition, it makes a new saving throw against the effect with Advantage."]]},{"k":"kor-dreambite","n":"Dream Bite","l":0,"s":"Dreamomancy","sa":"DRE","sp":["Abjuration","Illusion"],"c":["Bard","Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"60 feet","cp":"V, S","d":"Instantaneous","b":[["p","Make a ranged spell attack against a creature you can see within range. On a hit, the target takes 1d8 Psychic damage, and it can't take Reactions until the start of its next turn."]],"h":[["pb","Cantrip Upgrade","The damage increases by 1d8 when you reach levels 5 (2d8), 11 (3d8), and 17 (4d8)."]]},{"k":"kor-stumbleinthedark","n":"Stumble in the Dark","l":0,"s":"Dreamomancy","sa":"DRE","sp":["Abjuration","Illusion"],"c":["Bard","Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"60 feet","cp":"V, S","d":"Instantaneous","b":[["p","Choose a creature you can see within range. It feels the floor drop away and makes a Wisdom saving throw, taking 1d4 Psychic damage on a failed save. On a failed save, a Large or smaller creature also has the Prone condition."]],"h":[["pb","Cantrip Upgrade","The damage increases by 1d4 when you reach levels 5 (2d4), 11 (3d4), and 17 (4d4)."]]},{"k":"kor-nightmarepulse","n":"Nightmare Pulse","l":0,"s":"Dreamomancy","sa":"DRE","sp":["Abjuration","Illusion"],"c":["Bard","Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"Self (5-foot Emanation)","cp":"V, S","d":"Instantaneous","b":[["p","A wave of dread rolls out of you. Each creature of your choice in a 5-foot Emanation originating from you makes a Wisdom saving throw, taking 1d6 Psychic damage on a failed save."]],"h":[["pb","Cantrip Upgrade","The damage increases by 1d6 when you reach levels 5 (2d6), 11 (3d6), and 17 (4d6)."]]},{"k":"kor-dreamwhisper","n":"Dream Whisper","l":0,"s":"Dreamomancy","sa":"DRE","sp":["Abjuration","Illusion"],"c":["Bard","Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"1 mile","cp":"V, S","d":"1 round","b":[["p","Choose a creature you know that is asleep within range. You whisper up to 10 words into its dream. It remembers the message when it wakes."]]},{"k":"kor-lullaby","n":"Lullaby","l":0,"s":"Dreamomancy","sa":"DRE","sp":["Abjuration","Illusion"],"c":["Bard","Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"30 feet","cp":"V, S","d":"1 minute","b":[["p","You sing a lullaby to a creature you can see within range. If it is a Beast of Small size or smaller, or any creature that is already drowsy or willing, it makes a Wisdom saving throw (a willing creature can choose to fail). On a failed save, it falls asleep until the spell ends, takes damage, or someone uses an action to shake it awake."]]},{"k":"kor-powderflurry","n":"Powder Flurry","l":0,"s":"Sigilmancy","sa":"SIG","sp":["Evocation","Abjuration","Divination"],"c":["Druid","Sorcerer","Wizard"],"bk":"kor","ct":"Action","rg":"60 feet","cp":"V, S, M (a brush and ink)","d":"Instantaneous","b":[["p","Choose one creature you can see within range. It must succeed on a Constitution saving throw or take 1d6 Cold damage and have Disadvantage on the next attack roll it makes before the end of its next turn."],["pb","Sequence","If the last glyph is harsh, a creature that fails the save also has its Speed reduced by 10 feet until the end of its next turn."]],"h":[["pb","Cantrip Upgrade","The damage increases by 1d6 when you reach levels 5 (2d6), 11 (3d6) and 17 (4d6)."]],"ms":["Glyph: Snow"],"g":["Sigilmancy"]},{"k":"kor-snowfall","n":"Snowfall","l":0,"s":"Sigilmancy","sa":"SIG","sp":["Evocation","Abjuration","Divination"],"c":["Druid","Sorcerer","Wizard"],"bk":"kor","ct":"Action","rg":"60 feet","cp":"V, S, M (a brush and ink)","d":"1 minute","b":[["p","Snow falls in a 15-foot-radius, 20-foot-high Cylinder centered on a point within range. Nonmagical flames in the area are extinguished. Creatures have Disadvantage on Wisdom (Perception) checks that rely on hearing to notice something in or through the area. A creature that moves through the area leaves clear tracks, and creatures have Advantage on Wisdom (Survival) checks to follow them."],["pb","Sequence","If the last glyph is Seal, the duration is 1 hour."]],"ms":["Glyph: Snow"],"g":["Sigilmancy"]},{"k":"kor-packedcrust","n":"Packed Crust","l":0,"s":"Sigilmancy","sa":"SIG","sp":["Evocation","Abjuration","Divination"],"c":["Druid","Wizard"],"bk":"kor","ct":"Action","rg":"30 feet","cp":"V, S, M (a brush and ink)","d":"1 hour","b":[["p","Snow packs into a 10-foot square, 6-inch-thick crust on a surface within range, such as bare ground, thin ice, mud or water up to 1 foot deep. The area isn't Difficult Terrain, and each 5-foot square of it can bear up to 1,000 pounds."],["pb","Sequence","If the last glyph is Frost, the crust is ice instead of snow, bears up to 2,000 pounds per square, and lasts 8 hours."]],"ms":["Glyph: Snow"],"g":["Sigilmancy"]},{"k":"kor-hoarbite","n":"Hoarbite","l":0,"s":"Sigilmancy","sa":"SIG","sp":["Evocation","Abjuration","Divination"],"c":["Sorcerer","Wizard"],"bk":"kor","ct":"Action","rg":"60 feet","cp":"V, S, M (a brush and ink)","d":"Instantaneous","b":[["p","Make a ranged spell attack against a target within range. On a hit, the target takes 1d10 Cold damage."],["pb","Sequence","If the last glyph is Snow, the damage die is a d12."]],"h":[["pb","Cantrip Upgrade","The damage increases by 1d10 when you reach levels 5 (2d10), 11 (3d10) and 17 (4d10)."]],"ms":["Glyph: Frost"],"g":["Sigilmancy"]},{"k":"kor-froststroke","n":"Frost Stroke","l":0,"s":"Sigilmancy","sa":"SIG","sp":["Evocation","Abjuration","Divination"],"c":["Sorcerer","Wizard"],"bk":"kor","ct":"Action","rg":"Self (15-foot Line)","cp":"V, S, M (a brush and ink)","d":"Instantaneous","b":[["p","Each creature in a 15-foot Line originating from you makes a Dexterity saving throw, taking 1d6 Cold damage on a failed save."],["pb","Sequence","If the last glyph is Ruin, the damage ignores Resistance to Cold damage."]],"h":[["pb","Cantrip Upgrade","The damage increases by 1d6 when you reach levels 5 (2d6), 11 (3d6) and 17 (4d6)."]],"ms":["Glyph: Frost"],"g":["Sigilmancy"]},{"k":"kor-ironice","n":"Iron Ice","l":0,"s":"Sigilmancy","sa":"SIG","sp":["Evocation","Abjuration","Divination"],"c":["Cleric","Druid","Wizard"],"bk":"kor","ct":"Action","rg":"30 feet","cp":"V, S, M (a brush and ink)","d":"Instantaneous","b":[["p","Choose nonmagical liquid in a 10-foot cube within range, or an unattended mechanism within range, such as a hinge, wheel or winch. The liquid freezes solid, or the mechanism freezes in place for 1 hour. A creature can free a frozen mechanism with a Strength check against your spell save DC."],["pb","Sequence","If the last glyph is Seal, the ice or frozen mechanism can't be thawed by nonmagical heat for 1 hour."]],"ms":["Glyph: Frost"],"g":["Sigilmancy"]},{"k":"kor-pinningstroke","n":"Pinning Stroke","l":0,"s":"Sigilmancy","sa":"SIG","sp":["Evocation","Abjuration","Divination"],"c":["Cleric","Wizard"],"bk":"kor","ct":"Action","rg":"60 feet","cp":"V, S, M (a brush and ink)","d":"Instantaneous","b":[["p","Make a ranged spell attack against a target within range. On a hit, the target takes 1d8 Force damage and can't take Reactions until the start of its next turn."],["pb","Sequence","If the last glyph is Snow, the ink freezes on a hit. The target's Speed is also reduced by 10 feet until the end of its next turn."]],"h":[["pb","Cantrip Upgrade","The damage increases by 1d8 when you reach levels 5 (2d8), 11 (3d8) and 17 (4d8)."]],"ms":["Glyph: Seal"],"g":["Sigilmancy"]},{"k":"kor-sealingstroke","n":"Sealing Stroke","l":0,"s":"Sigilmancy","sa":"SIG","sp":["Evocation","Abjuration","Divination"],"c":["Cleric","Wizard"],"bk":"kor","ct":"Action","rg":"10 feet","cp":"V, S, M (a brush and ink)","d":"1 hour","b":[["p","Choose a closed door, window, gate, lid or container within range. You inscribe a sigil that locks it for the duration. A creature can open it with a Strength (Athletics) check or a Dexterity check using Thieves' Tools, against your spell save DC."],["pb","Sequence","If the last glyph is Paradise, you know when anyone forces the seal, if you are within 1 mile of it."]],"ms":["Glyph: Seal"],"g":["Sigilmancy"]},{"k":"kor-wardburst","n":"Wardburst","l":0,"s":"Sigilmancy","sa":"SIG","sp":["Evocation","Abjuration","Divination"],"c":["Cleric","Sorcerer","Wizard"],"bk":"kor","ct":"Action","rg":"Self (5-foot Emanation)","cp":"V, S, M (a brush and ink)","d":"Instantaneous","b":[["p","Each creature in a 5-foot Emanation originating from you makes a Strength saving throw. On a failed save, a creature takes 1d6 Force damage and is pushed up to 5 feet straight away from you."],["pb","Sequence","If the last glyph is Seal, the Emanation is 10 feet."]],"h":[["pb","Cantrip Upgrade","The damage increases by 1d6 when you reach levels 5 (2d6), 11 (3d6) and 17 (4d6)."]],"ms":["Glyph: Unleash"],"g":["Sigilmancy"]},{"k":"kor-breakstroke","n":"Breakstroke","l":0,"s":"Sigilmancy","sa":"SIG","sp":["Evocation","Abjuration","Divination"],"c":["Cleric","Sorcerer","Wizard"],"bk":"kor","ct":"Action","rg":"60 feet","cp":"V, S, M (a brush and ink)","d":"Instantaneous","b":[["p","Choose one creature you can see within range. It must succeed on a Constitution saving throw or take 1d8 Force damage. A creature that fails the save also has Disadvantage on Constitution saving throws to maintain Concentration until the start of your next turn."],["pb","Sequence","If the last glyph is Seal, a creature that fails the save also can't speak until the start of your next turn."]],"h":[["pb","Cantrip Upgrade","The damage increases by 1d8 when you reach levels 5 (2d8), 11 (3d8) and 17 (4d8)."]],"ms":["Glyph: Unleash"],"g":["Sigilmancy"]},{"k":"kor-looseningstroke","n":"Loosening Stroke","l":0,"s":"Sigilmancy","sa":"SIG","sp":["Evocation","Abjuration","Divination"],"c":["Cleric","Wizard"],"bk":"kor","ct":"Action","rg":"30 feet","cp":"V, S, M (a brush and ink)","d":"Instantaneous","b":[["p","Choose an object within range that is stuck, frozen shut, barred, or sealed by Sealing Stroke. It opens or breaks free with a loud crack audible within 300 feet. This doesn't affect a mechanical lock."],["pb","Sequence","If the last glyph is Seal, the crack makes no sound."]],"ms":["Glyph: Unleash"],"g":["Sigilmancy"]},{"k":"kor-fairomen","n":"Fair Omen","l":0,"s":"Sigilmancy","sa":"SIG","sp":["Evocation","Abjuration","Divination"],"c":["Cleric","Druid","Wizard"],"bk":"kor","ct":"1 minute","rg":"Self","cp":"V, S, M (a brush and ink)","d":"Instantaneous","b":[["p","You read the ice, snow or ink to see how the next hour will go if you and your companions continue as planned. You receive an omen of weal (no danger) or woe (danger within the hour), based on the most likely outcome. The omen doesn't say what the danger is."],["pb","Sequence","If the last glyph is Ruin and the omen is woe, you also learn the direction the danger will come from."]],"ms":["Glyph: Paradise"],"g":["Sigilmancy"]},{"k":"kor-kindmark","n":"Kind Mark","l":0,"s":"Sigilmancy","sa":"SIG","sp":["Evocation","Abjuration","Divination"],"c":["Cleric","Druid","Wizard"],"bk":"kor","ct":"Action","rg":"Touch","cp":"V, S, M (a brush and ink)","d":"1 hour","b":[["p","You draw a small sigil on a willing creature or an object you touch. For the duration, you know the direction and distance to the mark while it is within 1 mile of you. A creature can wipe the mark off with 1 minute of scrubbing. You can have only one Kind Mark active at a time."],["pb","Sequence","If the last glyph is Snow, water can't wash the mark off."]],"ms":["Glyph: Paradise"],"g":["Sigilmancy"]},{"k":"kor-doomglimpse","n":"Doom Glimpse","l":0,"s":"Sigilmancy","sa":"SIG","sp":["Evocation","Abjuration","Divination"],"c":["Cleric","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"60 feet","cp":"V, S, M (a brush and ink)","d":"Instantaneous","b":[["p","Choose one creature you can see within range. It must succeed on a Wisdom saving throw or take 1d6 Psychic damage, and the next attack roll made against it before the end of your next turn gains a +1d4 bonus."],["pb","Sequence","If the last glyph is Paradise, the bonus is +1d6."]],"h":[["pb","Cantrip Upgrade","The damage increases by 1d6 when you reach levels 5 (2d6), 11 (3d6) and 17 (4d6)."]],"ms":["Glyph: Ruin"],"g":["Sigilmancy"]},{"k":"kor-faultline","n":"Fault Line","l":0,"s":"Sigilmancy","sa":"SIG","sp":["Evocation","Abjuration","Divination"],"c":["Sorcerer","Wizard"],"bk":"kor","ct":"Action","rg":"60 feet","cp":"V, S, M (a brush and ink)","d":"1 minute","b":[["p","Choose a nonmagical object or structure within range. You learn its Hit Points and the spot where it will fail first. The first time within the duration that a single attack or effect deals damage to it, the damage is doubled."],["pb","Sequence","If the last glyph is Unleash, the first two instances of damage are doubled."]],"ms":["Glyph: Ruin"],"g":["Sigilmancy"]},{"k":"kor-gentlemantle","n":"Gentle Mantle","l":1,"s":"Sigilmancy","sa":"SIG","sp":["Evocation","Abjuration","Divination"],"c":["Cleric","Druid","Wizard"],"bk":"kor","ct":"Action","rg":"Touch","cp":"V, S, M (a brush and ink)","d":"1 hour","b":[["p","A mantle of soft snow settles over a willing creature you touch. The target gains 2d6 + 2 Temporary Hit Points and has Resistance to Cold damage while it has any of those Temporary Hit Points."],["pb","Sequence","If the last glyph is Paradise, roll the 2d6 twice and use the higher total."]],"h":[["p","The Temporary Hit Points increase by 5 for each spell slot level above 1."]],"ms":["Glyph: Snow"],"g":["Sigilmancy"]},{"k":"kor-hoarlance","n":"Hoar Lance","l":1,"s":"Sigilmancy","sa":"SIG","sp":["Evocation","Abjuration","Divination"],"c":["Sorcerer","Wizard"],"bk":"kor","ct":"Action","rg":"90 feet","cp":"V, S, M (a brush and ink)","d":"Instantaneous","b":[["p","Make a ranged spell attack against a target within range. On a hit, the target takes 3d8 Cold damage and its Speed is reduced by 10 feet until the end of its next turn."],["pb","Sequence","If the last glyph is Snow, the target's Speed is instead reduced to 0 until the end of its next turn."]],"h":[["p","The damage increases by 1d8 for each spell slot level above 1."]],"ms":["Glyph: Frost"],"g":["Sigilmancy"]},{"k":"kor-interposingseal","n":"Interposing Seal","l":1,"s":"Sigilmancy","sa":"SIG","sp":["Evocation","Abjuration","Divination"],"c":["Cleric","Wizard"],"bk":"kor","ct":"Reaction, which you take when a creature you can see within 30 feet of you takes damage","rg":"30 feet","cp":"V, S, M (a brush and ink)","d":"Instantaneous","b":[["p","An ink sigil blooms over the target and swallows part of the blow. Reduce the damage the target takes by 1d10 + your spellcasting ability modifier, to a minimum of 0."],["pb","Sequence","If the last glyph is Ruin, the reduction is 2d10 + your spellcasting ability modifier."]],"h":[["p","The reduction increases by 1d10 for each spell slot level above 1."]],"ms":["Glyph: Seal"],"g":["Sigilmancy"]},{"k":"kor-loosedward","n":"Loosed Ward","l":1,"s":"Sigilmancy","sa":"SIG","sp":["Evocation","Abjuration","Divination"],"c":["Cleric","Sorcerer","Wizard"],"bk":"kor","ct":"Action","rg":"Self (15-foot Cone)","cp":"V, S, M (a brush and ink)","d":"Instantaneous","b":[["p","Each creature in a 15-foot Cone makes a Strength saving throw. On a failed save, a creature takes 2d8 Force damage and is pushed up to 10 feet away from you. On a successful save, a creature takes half as much damage and isn't pushed."],["pb","Sequence","If the last glyph is Seal, the damage increases by 1d8."]],"h":[["p","The damage increases by 1d8 for each spell slot level above 1."]],"ms":["Glyph: Unleash"],"g":["Sigilmancy"]},{"k":"kor-fairroad","n":"Fair Road","l":1,"s":"Sigilmancy","sa":"SIG","sp":["Evocation","Abjuration","Divination"],"c":["Cleric","Druid","Wizard"],"bk":"kor","ct":"Action","rg":"30 feet","cp":"V, S, M (a brush and ink)","d":"Concentration, up to 8 hours","b":[["p","Choose up to five willing creatures within range. For the duration, each target can't become lost by nonmagical means, ignores the extra movement cost of Difficult Terrain made of snow, ice or mud, and has Advantage on Wisdom (Survival) checks to navigate."],["pb","Sequence","If the last glyph is Ruin, you learn the direction of the greatest danger on the road ahead, if it is within 1 mile."]],"con":1,"ms":["Glyph: Paradise"],"g":["Sigilmancy"]},{"k":"kor-snowboundveil","n":"Snowbound Veil","l":2,"s":"Sigilmancy","sa":"SIG","sp":["Evocation","Abjuration","Divination"],"c":["Druid","Sorcerer","Wizard"],"bk":"kor","ct":"Action","rg":"120 feet","cp":"V, S, M (a brush and ink)","d":"Concentration, up to 1 minute","b":[["p","Heavy snow falls in a 20-foot-radius Sphere centered on a point within range. The area is Heavily Obscured and counts as Difficult Terrain. Choose up to five creatures when you cast the spell. They ignore the extra movement cost and can see through the snow to a distance of 30 feet."],["pb","Sequence","If the last glyph is Frost, the ground freezes. A creature other than those you chose makes a Dexterity saving throw the first time it enters the area on a turn and the first time it starts its turn there. On a failed save, it has the Prone condition."]],"h":[["p","The radius increases by 5 feet for each spell slot level above 2."]],"con":1,"ms":["Glyph: Snow"],"g":["Sigilmancy"]},{"k":"kor-hailingscript","n":"Hailing Script","l":2,"s":"Sigilmancy","sa":"SIG","sp":["Evocation","Abjuration","Divination"],"c":["Sorcerer","Wizard"],"bk":"kor","ct":"Action","rg":"90 feet","cp":"V, S, M (a brush and ink)","d":"Instantaneous","b":[["p","Ink-black hail falls in a 10-foot-radius Sphere centered on a point within range. Each creature in the area makes a Dexterity saving throw, taking 3d8 Cold damage on a failed save or half as much damage on a successful one. On a failed save, a creature's Speed is also reduced by 10 feet until the end of its next turn."],["pb","Sequence","If the last glyph is Ruin, the damage ignores Resistance to Cold damage, and a creature with Immunity to Cold damage has Resistance to it instead."]],"h":[["p","The damage increases by 1d8 for each spell slot level above 2."]],"ms":["Glyph: Frost"],"g":["Sigilmancy"]},{"k":"kor-ingebornsthresholdwrit","n":"Ingeborn's Threshold Writ","l":2,"s":"Sigilmancy","sa":"SIG","sp":["Evocation","Abjuration","Divination"],"c":["Cleric","Wizard"],"bk":"kor","ct":"10 minutes or Ritual","rg":"Touch","cp":"V, S, M (a brush and ink worth 25 gp, which the spell consumes)","d":"8 hours or until triggered","b":[["p","Choose a doorway, window, gate or lid. You inscribe three glyphs on it in an order of your choice, and the Writ triggers once. A creature can take the Study action to read the glyphs."],["pb","First glyph (trigger)","Evocation: any creature that touches or passes the portal. Abjuration: any creature other than you and those you name. Divination: a creature of a type you name, such as Humanoid or Fiend."],["pb","Middle glyph (strength)","Gentle: the Writ deals no damage. Harsh: the triggering creature also takes 3d8 damage. The type is Cold for an Evocation last glyph, Force for Abjuration and Psychic for Divination."],["pb","Last glyph (result)","Evocation: ice grips the creature, and it must succeed on a Strength saving throw or have its Speed reduced to 0 until the end of its next turn. Abjuration: the portal locks until you open it or the DC to force it, equal to your spell save DC, is met, and the triggering creature is pushed 10 feet back. Divination: you are alerted if you are within 1 mile, and you learn what triggered the Writ."]],"rit":1,"ms":["Writ"],"g":["Sigilmancy"]},{"k":"kor-unravelingstrike","n":"Unraveling Strike","l":2,"s":"Sigilmancy","sa":"SIG","sp":["Evocation","Abjuration","Divination"],"c":["Cleric","Sorcerer","Wizard"],"bk":"kor","ct":"Action","rg":"60 feet","cp":"V, S, M (a brush and ink)","d":"Instantaneous","b":[["p","Make a ranged spell attack against a creature within range. On a hit, the target takes 4d8 Force damage, and you can end one spell affecting it of a level equal to or lower than the spell slot used + 1."],["pb","Sequence","If the last glyph is Seal, the maximum spell level you can end increases by 1."]],"h":[["p","The damage increases by 1d8 for each spell slot level above 2."]],"ms":["Glyph: Unleash"],"g":["Sigilmancy"]},{"k":"kor-faultintheice","n":"Fault in the Ice","l":2,"s":"Sigilmancy","sa":"SIG","sp":["Evocation","Abjuration","Divination"],"c":["Cleric","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"60 feet","cp":"V, S, M (a brush and ink)","d":"Concentration, up to 1 minute","b":[["p","Choose a creature you can see within range. A hairline fault is revealed in its defenses for the duration. Once per round, the first time a creature hits the target with an attack roll, the target takes an extra 1d6 Force damage."],["pb","Sequence","If the last glyph is Paradise, the extra damage is 1d8."]],"h":[["p","The duration is up to 10 minutes with a level 3 or 4 slot and up to 1 hour with a level 5 or higher slot."]],"con":1,"ms":["Glyph: Ruin"],"g":["Sigilmancy"]},{"k":"kor-skaldvarsglacialfan","n":"Skaldvar's Glacial Fan","l":3,"s":"Sigilmancy","sa":"SIG","sp":["Evocation","Abjuration","Divination"],"c":["Sorcerer","Wizard"],"bk":"kor","ct":"Action","rg":"Self (30-foot Cone)","cp":"V, S, M (a brush and ink)","d":"Instantaneous","b":[["p","Each creature in a 30-foot Cone makes a Constitution saving throw, taking 7d6 Cold damage on a failed save or half as much damage on a successful one. On a failed save, a creature's Speed is halved until the end of its next turn."],["pb","Sequence","If the last glyph is Snow, a creature that fails the save has its Speed reduced to 0 instead."]],"h":[["p","The damage increases by 1d6 for each spell slot level above 3."]],"ms":["Glyph: Frost"],"g":["Sigilmancy"]},{"k":"kor-ringofscript","n":"Ring of Script","l":3,"s":"Sigilmancy","sa":"SIG","sp":["Evocation","Abjuration","Divination"],"c":["Cleric","Wizard"],"bk":"kor","ct":"Action","rg":"60 feet","cp":"V, S, M (a brush and ink)","d":"Concentration, up to 1 minute","b":[["p","You draw a ring of ink script in a 10-foot-radius, 10-foot-high Cylinder centered on a point on a surface within range. Choose Cold, Force, Necrotic or Psychic. Creatures of your choice in the Cylinder when you cast the spell, and any creature you let into it later, have Resistance to that damage type while inside."],["pb","Sequence","If the last glyph is Unleash, the Resistance applies to a second damage type from that list."]],"h":[["p","The radius increases by 5 feet for each spell slot level above 3."]],"con":1,"ms":["Glyph: Seal"],"g":["Sigilmancy"]},{"k":"kor-loosedglyph","n":"Loosed Glyph","l":3,"s":"Sigilmancy","sa":"SIG","sp":["Evocation","Abjuration","Divination"],"c":["Cleric","Sorcerer","Wizard"],"bk":"kor","ct":"Action","rg":"Touch","cp":"V, S, M (a brush and ink worth 50 gp, which the spell consumes)","d":"Until dispelled or triggered","b":[["p","You inscribe a hidden glyph on a surface or object, covering up to a 5-foot square. It is invisible, and a creature can find it with a Study action (Intelligence (Arcana) check against your spell save DC). When a creature other than you or those you name steps on it, touches it, or opens the object, the glyph discharges. Each creature in a 15-foot-radius Sphere centered on the glyph makes a Dexterity saving throw, taking 6d8 Force damage on a failed save or half as much damage on a successful one."],["pb","Sequence","If the last glyph is Seal, the damage is 7d8."]],"h":[["p","The damage increases by 1d8 for each spell slot level above 3."]],"ms":["Glyph: Unleash"],"g":["Sigilmancy"]},{"k":"kor-kindlyomen","n":"Kindly Omen","l":3,"s":"Sigilmancy","sa":"SIG","sp":["Evocation","Abjuration","Divination"],"c":["Cleric","Druid","Wizard"],"bk":"kor","ct":"Reaction, which you take when a creature you can see within 60 feet fails a saving throw","rg":"60 feet","cp":"V, S, M (a brush and ink)","d":"Instantaneous","b":[["p","You glimpse a kinder outcome. The target rerolls the failed saving throw and must use the new roll."],["pb","Sequence","If the last glyph is Ruin, the new roll gains a +1d4 bonus."]],"ms":["Glyph: Paradise"],"g":["Sigilmancy"]},{"k":"kor-finalfault","n":"Final Fault","l":3,"s":"Sigilmancy","sa":"SIG","sp":["Evocation","Abjuration","Divination"],"c":["Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"90 feet","cp":"V, S, M (a brush and ink)","d":"Instantaneous","b":[["p","Make a ranged spell attack against a target within range. On a hit, the target takes 6d8 Force damage, or 8d8 if it is Bloodied."],["pb","Sequence","If the last glyph is Paradise, treat the target as Bloodied."]],"h":[["p","The damage increases by 1d8 for each spell slot level above 3."]],"ms":["Glyph: Ruin"],"g":["Sigilmancy"]},{"k":"kor-winterskeeping","n":"Winter's Keeping","l":4,"s":"Sigilmancy","sa":"SIG","sp":["Evocation","Abjuration","Divination"],"c":["Cleric","Druid","Wizard"],"bk":"kor","ct":"Action","rg":"Touch","cp":"V, S, M (a brush and ink)","d":"8 hours","b":[["p","Snow and rime close over a creature you touch that has 0 Hit Points. For the duration, the target is Stable and doesn't make death saving throws. Effects that would deal damage to it over time, or that would advance a disease or poison, are paused. The spell ends if the target regains any Hit Points or takes damage."],["pb","Sequence","If the last glyph is Ruin, you learn what reduced the target to 0 Hit Points and whether a curse, poison or disease is affecting it."]],"ms":["Glyph: Snow"],"g":["Sigilmancy"]},{"k":"kor-inkwolf","n":"Inkwolf","l":4,"s":"Sigilmancy","sa":"SIG","sp":["Evocation","Abjuration","Divination"],"c":["Sorcerer","Wizard"],"bk":"kor","ct":"Action","rg":"60 feet","cp":"V, S, M (a brush and ink)","d":"Concentration, up to 1 minute","b":[["p","You brush a wolf of black ink onto the air in an unoccupied space within range. It is a spectral force, not a creature, and it can't be targeted by attacks or spells. When you cast the spell, and as a Bonus Action on each of your later turns, you can move the wolf up to 30 feet and make a melee spell attack against a creature within 5 feet of it. On a hit, the target takes 3d8 Cold damage."],["pb","Sequence","If the last glyph is Snow, a creature the wolf hits also has its Speed reduced by 10 feet until the start of your next turn."]],"h":[["p","The damage increases by 1d8 for each spell slot level above 4."]],"con":1,"ms":["Glyph: Frost"],"g":["Sigilmancy"]},{"k":"kor-lettersofbinding","n":"Letters of Binding","l":4,"s":"Sigilmancy","sa":"SIG","sp":["Evocation","Abjuration","Divination"],"c":["Cleric","Wizard"],"bk":"kor","ct":"Action","rg":"60 feet","cp":"V, S, M (a brush and ink)","d":"Concentration, up to 1 minute","b":[["p","Choose up to two creatures you can see within range. Each must succeed on a Strength saving throw or have the Restrained condition as bands of script wrap around it. A Restrained creature can take an action to make a Strength (Athletics) or Dexterity (Acrobatics) check against your spell save DC, ending the condition on itself on a success."],["pb","Sequence","If the last glyph is Snow, the script is frozen and each creature has Disadvantage on that check."]],"h":[["p","You can target one additional creature for each spell slot level above 4."]],"con":1,"ms":["Glyph: Seal"],"g":["Sigilmancy"]},{"k":"kor-twinpools","n":"Twin Pools","l":4,"s":"Sigilmancy","sa":"SIG","sp":["Evocation","Abjuration","Divination"],"c":["Cleric","Druid","Wizard"],"bk":"kor","ct":"1 minute","rg":"Touch","cp":"V, S, M (two bowls and ink worth 100 gp, which the spell consumes)","d":"Concentration, up to 1 hour","b":[["p","You pour ink into two bowls, and the pools become linked. Keep one bowl with you and place the other anywhere. While you are within 1 mile of the far bowl, you can see and hear its surroundings out to 30 feet as if you stood beside it. The spell ends if either bowl is spilled or covered."],["pb","Sequence","If the last glyph is Seal, the far bowl can't be detected by divination magic and is invisible to creatures that look at it."]],"con":1,"ms":["Glyph: Paradise"],"g":["Sigilmancy"]},{"k":"kor-writofthelongwatch","n":"Writ of the Long Watch","l":4,"s":"Sigilmancy","sa":"SIG","sp":["Evocation","Abjuration","Divination"],"c":["Cleric","Wizard"],"bk":"kor","ct":"10 minutes or Ritual","rg":"Touch","cp":"V, S, M (a brush and ink worth 100 gp, which the spell consumes)","d":"8 hours or until triggered","b":[["p","You inscribe three glyphs in an order of your choice around a point you touch. The Writ guards a 30-foot-radius Sphere centered on that point and triggers once. A creature can take the Study action to read the glyphs."],["pb","First glyph (trigger)","Evocation: any creature that enters the area. Abjuration: any creature other than you and those you name that enters. Divination: a creature of a type you name that enters."],["pb","Middle glyph (strength)","Gentle: the Writ deals no damage. Harsh: the triggering creature takes 6d8 damage. The type is Cold for an Evocation last glyph, Force for Abjuration and Psychic for Divination."],["pb","Last glyph (result)","Evocation: freezing wind fills the area for 1 minute, making it Difficult Terrain for creatures other than you and those you name. Abjuration: the triggering creature is pushed to the nearest unoccupied space outside the area, and walls of script keep out everyone other than you and those you name for 1 minute. Divination: you are alerted if you are within 1 mile, and you see through the Writ's area for 1 minute as if you stood in it."]],"rit":1,"ms":["Writ"],"g":["Sigilmancy"]},{"k":"kor-mendingsnow","n":"Mending Snow","l":5,"s":"Sigilmancy","sa":"SIG","sp":["Evocation","Abjuration","Divination"],"c":["Cleric","Druid","Wizard"],"bk":"kor","ct":"Action","rg":"90 feet","cp":"V, S, M (a brush and ink)","d":"Concentration, up to 1 minute","b":[["p","Gentle snow falls in a 30-foot-radius, 20-foot-high Cylinder centered on a point within range. Creatures of your choice in the area have Resistance to Cold damage. At the start of each of your turns, each of them gains 1d8 + your spellcasting ability modifier Temporary Hit Points. The area is Difficult Terrain for other creatures."],["pb","Sequence","If the last glyph is Paradise, the die is a d10."]],"h":[["p","The Temporary Hit Points increase by 5 for each spell slot level above 5."]],"con":1,"ms":["Glyph: Snow"],"g":["Sigilmancy"]},{"k":"kor-hallveigswallofsealedscript","n":"Hallveig's Wall of Sealed Script","l":5,"s":"Sigilmancy","sa":"SIG","sp":["Evocation","Abjuration","Divination"],"c":["Cleric","Wizard"],"bk":"kor","ct":"Action","rg":"120 feet","cp":"V, S, M (a brush and ink)","d":"Concentration, up to 10 minutes","b":[["p","A wall of glowing script rises on a solid surface within range. It is a straight line up to 60 feet long, 20 feet high and 1 foot thick, or a ring up to 20 feet in diameter with the same height and thickness. Creatures and objects other than you and those you name can't pass through it. Attacks and spells can pass. Each 10-foot section has AC 15, 40 Hit Points and Immunity to Poison and Psychic damage, and a destroyed section ends."],["pb","Sequence","If the last glyph is Unleash, each creature that touches the wall for the first time on a turn takes 4d8 Force damage."]],"h":[["p","The wall's length increases by 20 feet for each spell slot level above 5."]],"con":1,"ms":["Glyph: Seal"],"g":["Sigilmancy"]},{"k":"kor-rendingdischarge","n":"Rending Discharge","l":5,"s":"Sigilmancy","sa":"SIG","sp":["Evocation","Abjuration","Divination"],"c":["Cleric","Sorcerer","Wizard"],"bk":"kor","ct":"Action","rg":"120 feet","cp":"V, S, M (a brush and ink)","d":"Instantaneous","b":[["p","Stored force bursts in a 15-foot-radius Sphere centered on a point within range. Each creature in the area makes a Strength saving throw, taking 8d8 Force damage on a failed save or half as much damage on a successful one. A creature that fails the save is also pushed up to 15 feet away from the center."],["pb","Sequence","If the last glyph is Seal, the Sphere has a 20-foot radius."]],"h":[["p","The damage increases by 1d8 for each spell slot level above 5."]],"ms":["Glyph: Unleash"],"g":["Sigilmancy"]},{"k":"kor-readingofruin","n":"Reading of Ruin","l":5,"s":"Sigilmancy","sa":"SIG","sp":["Evocation","Abjuration","Divination"],"c":["Cleric","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"90 feet","cp":"V, S, M (a brush and ink)","d":"Concentration, up to 1 minute","b":[["p","Choose a creature you can see within range. It must succeed on a Wisdom saving throw or take 4d6 Psychic damage and have Vulnerability to Cold, Force and Psychic damage for the duration."],["pb","Sequence","If the last glyph is Paradise, the target has Disadvantage on the saving throw."]],"h":[["p","The damage increases by 1d6 for each spell slot level above 5."]],"con":1,"ms":["Glyph: Ruin"],"g":["Sigilmancy"]},{"k":"kor-writoftheicemoot","n":"Writ of the Ice-Moot","l":5,"s":"Sigilmancy","sa":"SIG","sp":["Evocation","Abjuration","Divination"],"c":["Cleric","Wizard"],"bk":"kor","ct":"1 hour or Ritual","rg":"Touch","cp":"V, S, M (a brush and ink worth 100 gp, which the spell consumes)","d":"24 hours","b":[["p","You inscribe three glyphs in an order of your choice in a hall or other area up to 60 feet in radius. Creatures bound by the Writ keep a truce. A creature can take the Study action to read the glyphs."],["pb","First glyph (who is bound)","Evocation: every creature in the area. Abjuration: every creature except you and those you name. Divination: only creatures that willingly swear to the truce on entering."],["pb","Middle glyph (enforcement)","Gentle: a bound creature that tries to harm another bound creature must first succeed on a Wisdom saving throw, or it loses the action and the attempt fails. Harsh: a bound creature that harms another bound creature takes 6d8 damage. The type is Cold for an Evocation last glyph, Force for Abjuration and Psychic for Divination."],["pb","Last glyph (consequence)","Evocation: ice grips the oath-breaker, reducing its Speed to 0 until the end of its next turn. Abjuration: the oath-breaker is cast out of the area and can't re-enter for 24 hours. Divination: the oath-breaker is marked, and you know its name and location while within 1 mile for 24 hours."]],"rit":1,"ms":["Writ"],"g":["Sigilmancy"]},{"k":"kor-torvhildswhiteout","n":"Torvhild's Whiteout","l":6,"s":"Sigilmancy","sa":"SIG","sp":["Evocation","Abjuration","Divination"],"c":["Sorcerer","Wizard"],"bk":"kor","ct":"Action","rg":"150 feet","cp":"V, S, M (a brush and ink)","d":"Instantaneous","b":[["p","A storm of ink-dark hail and snow breaks in a 20-foot-radius Sphere centered on a point within range. Each creature in the area makes a Constitution saving throw, taking 10d6 Cold damage on a failed save or half as much damage on a successful one. On a failed save, a creature's Speed is reduced to 0 until the end of its next turn."],["pb","Sequence","If the last glyph is Snow, a creature that fails the save also has Disadvantage on attack rolls until the end of its next turn."]],"h":[["p","The damage increases by 1d6 for each spell slot level above 6."]],"ms":["Glyph: Frost"],"g":["Sigilmancy"]},{"k":"kor-paradiseforetold","n":"Paradise Foretold","l":6,"s":"Sigilmancy","sa":"SIG","sp":["Evocation","Abjuration","Divination"],"c":["Cleric","Druid","Wizard"],"bk":"kor","ct":"Action","rg":"60 feet","cp":"V, S, M (a brush and ink)","d":"Concentration, up to 1 minute","b":[["p","Choose up to six willing creatures within range. For the duration, each target can reroll one D20 Test it fails and must use the new roll. A target's reroll is expended once used."],["pb","Sequence","If the last glyph is Ruin, a rerolled D20 Test gains a +1d4 bonus."]],"con":1,"ms":["Glyph: Paradise"],"g":["Sigilmancy"]},{"k":"kor-reckoning","n":"Reckoning","l":6,"s":"Sigilmancy","sa":"SIG","sp":["Evocation","Abjuration","Divination"],"c":["Cleric","Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"90 feet","cp":"V, S, M (a brush and ink)","d":"Instantaneous","b":[["p","Choose a creature you can see within range. It makes a Wisdom saving throw, taking 8d8 Psychic damage on a failed save or half as much damage on a successful one. On a failed save, the creature also can't regain Hit Points until the end of its next turn."],["pb","Sequence","If the last glyph is Paradise, the damage dice are d10s."]],"h":[["p","The damage increases by 1d8 (or 1d10 with the Sequence) for each spell slot level above 6."]],"ms":["Glyph: Ruin"],"g":["Sigilmancy"]},{"k":"kor-writofthefrostseal","n":"Writ of the Frost-Seal","l":6,"s":"Sigilmancy","sa":"SIG","sp":["Evocation","Abjuration","Divination"],"c":["Cleric","Wizard"],"bk":"kor","ct":"1 hour or Ritual","rg":"Touch","cp":"V, S, M (a brush and ink worth 250 gp, which the spell consumes)","d":"24 hours","b":[["p","You inscribe three glyphs in an order of your choice on the threshold of a building or at the center of an area up to 60 feet in radius. A creature can take the Study action to read the glyphs."],["pb","First glyph (what it guards against)","Evocation: any creature that enters the area without being named by you. Abjuration: any spell of level 5 or lower cast into or within the area by a creature you haven't named, which fails. Divination: any attempt to scry on the area or its occupants, which fails and alerts you."],["pb","Middle glyph (strength)","Gentle: the Writ only blocks or alerts. Harsh: the Writ also deals 8d8 damage to the intruder or caster. The type is Cold for an Evocation last glyph, Force for Abjuration and Psychic for Divination."],["pb","Last glyph (result)","Evocation: a blizzard fills the area for 1 hour, and creatures other than you and those you name have Disadvantage on attack rolls and ability checks while in it. Abjuration: the area is warded against teleportation for 24 hours. Divination: you gain a lasting link to the area, and you see through it for 1 hour as if you stood within it."]],"rit":1,"ms":["Writ"],"g":["Sigilmancy"]},{"k":"kor-ormundslastline","n":"Ormund's Last Line","l":7,"s":"Sigilmancy","sa":"SIG","sp":["Evocation","Abjuration","Divination"],"c":["Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"90 feet","cp":"V, S, M (a brush and ink)","d":"Instantaneous","b":[["p","You read your own Script aloud as a closing line. Choose a creature you can see within range. It makes a Wisdom saving throw, taking 7d8 Psychic damage plus 3d8 for each glyph in your Script on a failed save, or half as much damage on a successful one."]],"h":[["p","The base damage increases by 1d8 for each spell slot level above 7."]],"ms":["Glyph: Ruin","Script-reading"],"g":["Sigilmancy"]},{"k":"kor-cageofscript","n":"Cage of Script","l":7,"s":"Sigilmancy","sa":"SIG","sp":["Evocation","Abjuration","Divination"],"c":["Cleric","Wizard"],"bk":"kor","ct":"Action","rg":"100 feet","cp":"V, S, M (a brush and ink)","d":"Concentration, up to 1 hour","b":[["p","A cage of lettered bars rises in a 20-foot Cube centered on a point within range. Creatures in the Cube make a Dexterity saving throw, and on a success they move to the nearest unoccupied space outside it. Creatures and objects that remain can't leave by nonmagical means. Attacks and spells can pass through the bars. A creature inside can take an action to make a Strength (Athletics) check against your spell save DC. On a success, it forces a gap, and the gap closes at the end of its turn."],["pb","Sequence","If the last glyph is Snow, the bars are frozen and the creature has Disadvantage on that check."]],"h":[["p","The Cube's side increases by 5 feet for each spell slot level above 7."]],"con":1,"ms":["Glyph: Seal"],"g":["Sigilmancy"]},{"k":"kor-mercyforeseen","n":"Mercy Foreseen","l":7,"s":"Sigilmancy","sa":"SIG","sp":["Evocation","Abjuration","Divination"],"c":["Cleric","Druid","Wizard"],"bk":"kor","ct":"Action","rg":"30 feet","cp":"V, S, M (a brush and ink)","d":"Concentration, up to 1 minute","b":[["p","Choose up to eight willing creatures within range. The first time during the duration that a target would be reduced to 0 Hit Points, it drops to 1 Hit Point instead, and the effect ends for that target."],["pb","Sequence","If the last glyph is Ruin, a target saved this way also has Resistance to the damage type that triggered it until the end of its next turn."]],"h":[["p","You can target two additional creatures for each spell slot level above 7."]],"con":1,"ms":["Glyph: Paradise"],"g":["Sigilmancy"]},{"k":"kor-writofthehush","n":"Writ of the Hush","l":7,"s":"Sigilmancy","sa":"SIG","sp":["Evocation","Abjuration","Divination"],"c":["Cleric","Warlock","Wizard"],"bk":"kor","ct":"1 hour or Ritual","rg":"Touch","cp":"V, S, M (a brush and ink worth 500 gp, which the spell consumes)","d":"30 days or until triggered","b":[["p","You inscribe three glyphs on an object and name one creature. The Writ triggers once, and a creature can find it with the Study action (Intelligence (Arcana) check against your spell save DC). Remove Curse can end it before it triggers."],["pb","First glyph (trigger)","Evocation: the named creature touches the object. Abjuration: it wields, wears or uses the object. Divination: it comes within 5 feet of the object."],["pb","Middle glyph (strength)","Gentle: the result lasts 24 hours. Harsh: the creature also makes a Constitution saving throw, taking 10d8 damage on a failed save or half as much on a successful one, and the result lasts until Remove Curse ends it. The damage type is Cold for an Evocation last glyph, Force for Abjuration and Psychic for Divination."],["pb","Last glyph (result)","Evocation: the creature gains 2 Exhaustion levels. Abjuration: it can't speak or cast spells with a Verbal component. Divination: it has Disadvantage on saving throws, and you know its location while it is within 1 mile."],["p","If the damage reduces the creature to 0 Hit Points, its body shows only the marks of exposure (Cold), a fall through thin ice (Force) or a failing heart (Psychic)."]],"rit":1,"ms":["Writ"],"g":["Sigilmancy"]},{"k":"kor-hoarfrosttomb","n":"Hoarfrost Tomb","l":8,"s":"Sigilmancy","sa":"SIG","sp":["Evocation","Abjuration","Divination"],"c":["Sorcerer","Wizard"],"bk":"kor","ct":"Action","rg":"120 feet","cp":"V, S, M (a brush and ink)","d":"Instantaneous","b":[["p","Choose a creature you can see within range. It makes a Constitution saving throw, taking 11d8 Cold damage on a failed save or half as much damage on a successful one. A creature that fails the save is also Restrained in ice until the end of its next turn."],["pb","Sequence","If the last glyph is Snow, a creature that fails the save also has the Incapacitated condition until the end of its next turn."]],"h":[["p","The damage increases by 2d8 for each spell slot level above 8."]],"ms":["Glyph: Frost"],"g":["Sigilmancy"]},{"k":"kor-ulfhildsgreatunleashing","n":"Ulfhild's Great Unleashing","l":8,"s":"Sigilmancy","sa":"SIG","sp":["Evocation","Abjuration","Divination"],"c":["Cleric","Sorcerer","Wizard"],"bk":"kor","ct":"Action","rg":"Self (40-foot Emanation)","cp":"V, S, M (a brush and ink)","d":"Instantaneous","b":[["p","Each creature in a 40-foot Emanation originating from you makes a Constitution saving throw, taking 10d10 Force damage on a failed save or half as much damage on a successful one. In addition, for each creature or object in the area, you can end one spell of level 5 or lower affecting it, other than your own."],["pb","Sequence","If the last glyph is Seal, choose any number of creatures in the area. They are unaffected."]],"h":[["p","The damage increases by 1d10 for each spell slot level above 8."]],"ms":["Glyph: Unleash"],"g":["Sigilmancy"]},{"k":"kor-eirunnslongwinter","n":"Eirunn's Long Winter","l":8,"s":"Sigilmancy","sa":"SIG","sp":["Evocation","Abjuration","Divination"],"c":["Cleric","Druid","Wizard"],"bk":"kor","ct":"1 hour","rg":"Touch","cp":"V, S, M (a brush and ink worth 500 gp, which the spell consumes)","d":"Up to 1 year","b":[["p","You lay up to eight willing creatures in snow and write the long sleep over them. Each falls into a deathlike hibernation for the duration. It has the Unconscious condition, doesn't age, doesn't need food, water or air, is immune to Cold damage, and can't be detected by divination magic. When you cast the spell, choose a condition that ends the sleep, such as a date or a spoken word. The sleep ends for a creature early if it takes damage."],["pb","Sequence","If the last glyph is Paradise, a creature wakes at full Hit Points with the benefits of a Long Rest."]],"h":[["p","With a level 9 slot, the duration is up to 100 years."]],"ms":["Glyph: Snow"],"g":["Sigilmancy"]},{"k":"kor-writofthefrozenverdict","n":"Writ of the Frozen Verdict","l":8,"s":"Sigilmancy","sa":"SIG","sp":["Evocation","Abjuration","Divination"],"c":["Cleric","Wizard"],"bk":"kor","ct":"1 hour or Ritual","rg":"Touch","cp":"V, S, M (a brush and ink worth 1,000 gp, which the spell consumes)","d":"Until released","b":[["p","The target must be willing, Restrained or Incapacitated, or a creature that broke the terms of a Writ of the Ice-Moot. You inscribe three glyphs on ice or stone beside it."],["pb","First glyph (terms of release)","Evocation: after a time you set, up to 1 year. Abjuration: when a condition you state is met. Divination: when a named creature speaks a chosen word in its presence."],["pb","Middle glyph (state)","Gentle: the target sleeps. Harsh: it stays conscious and aware."],["pb","Last glyph (container)","Evocation: the target is entombed in a block of ice with AC 20, 150 Hit Points and Immunity to Cold, Poison and Psychic damage. Abjuration: the Writ can't be harmed, and the target can be freed only by meeting the terms, by Dispel Magic cast with a level 9 slot, or by Wish. Divination: you know the target's location and condition while it is on the same continent."]],"rit":1,"ms":["Writ"],"g":["Sigilmancy"]},{"k":"kor-vigdrunsfinalpage","n":"Vigdrun's Final Page","l":9,"s":"Sigilmancy","sa":"SIG","sp":["Evocation","Abjuration","Divination"],"c":["Cleric","Sorcerer","Warlock","Wizard"],"bk":"kor","ct":"Action","rg":"120 feet","cp":"V, S, M (a brush and ink)","d":"Instantaneous","b":[["p","You write the last page of a creature's story. Choose a creature you can see within range. It makes a Wisdom saving throw, taking 14d10 Psychic damage on a failed save or half as much damage on a successful one. If your Script contains an Evocation glyph, an Abjuration glyph and a Divination glyph (any tiers), the damage ignores Resistance, a creature with Immunity to Psychic damage has Resistance instead, and a creature reduced to 0 Hit Points by it dies."]],"ms":["Glyph: Ruin","Script-reading"],"g":["Sigilmancy"]},{"k":"kor-writofthepackice","n":"Writ of the Pack Ice","l":9,"s":"Sigilmancy","sa":"SIG","sp":["Evocation","Abjuration","Divination"],"c":["Druid","Wizard"],"bk":"kor","ct":"8 hours or Ritual","rg":"Touch","cp":"V, S, M (a brush and ink worth 2,500 gp, which the spell consumes)","d":"Up to 30 days","b":[["p","You inscribe three glyphs at the edge of a body of water. Over the next hour it freezes, as a roughly circular area up to the radius below. The ice lasts for the duration, or until you end it."],["pb","First glyph (extent)","Evocation: 1-mile radius. Abjuration: 3-mile radius. Divination: 5-mile radius, and you shape its outline."],["pb","Middle glyph (thickness)","Gentle: 3 feet thick, enough for cavalry and carts. Harsh: 30 feet thick, enough for siege engines."],["pb","Last glyph (effect)","Evocation: ships and creatures in the water when it freezes are held fast, and creatures in the water are Restrained. Abjuration: ships you name keep a channel open and float free. Divination: you can see and hear through any point of the ice."]],"rit":1,"ms":["Writ"],"g":["Sigilmancy"]},{"k":"kor-writoftheoldice","n":"Writ of the Old Ice","l":9,"s":"Sigilmancy","sa":"SIG","sp":["Evocation","Abjuration","Divination"],"c":["Cleric","Wizard"],"bk":"kor","ct":"1 hour or Ritual","rg":"Self","cp":"V, S, M (a brush and ink worth 1,000 gp, which the spell consumes, and a piece of ice at least 1 foot across taken from the place you wish to see)","d":"Concentration, up to 1 hour","b":[["p","You read the past of a place through the ice that stood there."],["pb","First glyph (how far back)","Evocation: up to 10 years. Abjuration: up to 100 years. Divination: up to 1,000 years."],["pb","Middle glyph (clarity)","Gentle: you see a silent, blurred image. Harsh: sight and sound are clear, but you take 6d8 Psychic damage when the casting ends, with no saving throw."],["pb","Last glyph (focus)","Evocation: a single event you name, such as a battle or a death. Abjuration: the presence of a specific creature or object you name. Divination: a truth about the place or event you name, which the DM answers in a single sentence."]],"con":1,"rit":1,"ms":["Writ"],"g":["Sigilmancy"]},{"k":"kor-standingorder","n":"Standing Order","l":0,"s":"Wardamancy","sa":"WAR","sp":["Abjuration","Transmutation","Enchantment"],"c":["Artificer","Bard","Cleric","Wizard"],"bk":"kor","ct":"Action","rg":"30 feet","cp":"V, S, M (a scrap of cloth or metal, which serves as the Anchor)","d":"Concentration, up to 1 minute","b":[["p","State a Goal and set the spell on an Anchor within range. A 10-foot Emanation originates from the Anchor for the duration. Once on each of its turns, a counted creature in the Emanation can add 1d4 to a saving throw it makes against the Frightened condition or against being moved against its will."],["pb","Unity","If Unity is 4 or more, the die is 1d6."]],"con":1,"ms":["Anchored","Unity"],"g":["Wardamancy"]},{"k":"kor-settheedge","n":"Set the Edge","l":0,"s":"Wardamancy","sa":"WAR","sp":["Abjuration","Transmutation","Enchantment"],"c":["Artificer","Cleric","Sorcerer","Wizard"],"bk":"kor","ct":"Action","rg":"30 feet","cp":"V, S, M (a scrap of cloth or metal, which serves as the Anchor)","d":"Concentration, up to 1 minute","b":[["p","State a Goal and set the spell on an Anchor within range. A 10-foot Emanation originates from the Anchor for the duration. The weapons counted creatures carry in the Emanation take a keener edge."],["pb","Unity","If Unity is 4 or more, once on each of its turns, a counted creature in the Emanation that hits with a weapon attack deals 1 extra damage of the weapon's type."]],"h":[["pb","Cantrip Upgrade","The extra damage increases by 1 when you reach levels 5 (2), 11 (3) and 17 (4)."]],"con":1,"ms":["Anchored","Unity"],"g":["Wardamancy"]},{"k":"kor-phalanxpush","n":"Phalanx Push","l":0,"s":"Wardamancy","sa":"WAR","sp":["Abjuration","Transmutation","Enchantment"],"c":["Artificer","Cleric","Sorcerer","Wizard"],"bk":"kor","ct":"Action","rg":"30 feet","cp":"V, S","d":"Instantaneous","b":[["p","State a Goal. Choose one creature you can see within range. It must succeed on a Strength saving throw or take 1d6 Force damage and be pushed up to 5 feet straight away from you."],["pb","Unity","If Unity is 4 or more, a creature that fails the save also has its Speed reduced to 0 until the end of its next turn."]],"h":[["pb","Cantrip Upgrade","The damage increases by 1d6 when you reach levels 5 (2d6), 11 (3d6) and 17 (4d6)."]],"ms":["Unity"],"g":["Wardamancy"]},{"k":"kor-sentrystone","n":"Sentry Stone","l":0,"s":"Wardamancy","sa":"WAR","sp":["Abjuration","Transmutation","Enchantment"],"c":["Artificer","Cleric","Wizard"],"bk":"kor","ct":"Action","rg":"Touch","cp":"V, S, M (a stone or iron peg, which serves as the Anchor)","d":"1 hour","b":[["p","You set a stone or peg into a surface. A 20-foot Emanation originates from the Anchor for the duration. You hear a chime in your mind when a creature you haven't named enters the Emanation, as long as you are within 1 mile of the Anchor. The chime doesn't wake you."]],"ms":["Anchored"],"g":["Wardamancy"]},{"k":"kor-rankandcall","n":"Rank and Call","l":0,"s":"Wardamancy","sa":"WAR","sp":["Abjuration","Transmutation","Enchantment"],"c":["Bard","Cleric","Wizard"],"bk":"kor","ct":"Action","rg":"Self (60-foot Emanation)","cp":"V, S","d":"1 hour","b":[["p","State a Goal. Willing creatures in the Emanation who share it become counted creatures for the duration. You and the counted creatures can speak in a normal voice to each other and be heard clearly within 300 feet, and no one else hears it. For the duration, you don't need to state a new Goal when you cast other Wardamancy spells."],["pb","Unity","If Unity is 4 or more, each counted creature also knows the direction to you."]],"ms":["Unity"],"g":["Wardamancy"]},{"k":"kor-shieldwall","n":"Shieldwall","l":1,"s":"Wardamancy","sa":"WAR","sp":["Abjuration","Transmutation","Enchantment"],"c":["Artificer","Cleric","Paladin","Wizard"],"bk":"kor","ct":"Action","rg":"30 feet","cp":"V, S, M (a shield or plate, which serves as the Anchor)","d":"Concentration, up to 1 minute","b":[["p","State a Goal and set the spell on an Anchor within range. A 15-foot Emanation originates from the Anchor for the duration."],["pb","Unity","If Unity is 3 or more, counted creatures in the Emanation can't be pushed, pulled or knocked Prone against their will."]],"h":[["p","The Emanation's radius increases by 5 feet for each spell slot level above 1."]],"con":1,"ms":["Anchored","Unity"],"g":["Wardamancy"]},{"k":"kor-rallycry","n":"Rally Cry","l":1,"s":"Wardamancy","sa":"WAR","sp":["Abjuration","Transmutation","Enchantment"],"c":["Bard","Cleric","Paladin","Wizard"],"bk":"kor","ct":"Bonus Action","rg":"Self (30-foot Emanation)","cp":"V","d":"Instantaneous","b":[["p","State a Goal. Each counted creature in the Emanation gains Temporary Hit Points equal to Unity and can end the Frightened condition on itself."]],"h":[["p","The Temporary Hit Points increase by 2 for each spell slot level above 1."]],"ms":["Unity"],"g":["Wardamancy"]},{"k":"kor-focusfire","n":"Focus Fire","l":1,"s":"Wardamancy","sa":"WAR","sp":["Abjuration","Transmutation","Enchantment"],"c":["Bard","Cleric","Paladin","Ranger","Wizard"],"bk":"kor","ct":"Bonus Action","rg":"60 feet","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","State a Goal and choose a creature you can see within range. Each round, the first times a counted creature hits the target with an attack roll, the target takes 1d4 extra damage of the attack's type. The extra damage can be dealt a number of times each round equal to half of Unity (round down, minimum 1)."]],"h":[["p","The die becomes a d6 with a level 3 or 4 slot and a d8 with a level 5 or higher slot."]],"con":1,"ms":["Unity"],"g":["Wardamancy"]},{"k":"kor-fieldrepair","n":"Field Repair","l":1,"s":"Wardamancy","sa":"WAR","sp":["Abjuration","Transmutation","Enchantment"],"c":["Artificer","Bard","Cleric","Wizard"],"bk":"kor","ct":"1 minute","rg":"Touch","cp":"V, S, M (a hammer, needle or set of tools)","d":"Instantaneous","b":[["p","State a Goal and touch a damaged nonmagical object. It regains 4d8 Hit Points, and a break or tear in it no larger than 1 foot across is mended. You can repeat this on up to a number of additional damaged nonmagical objects equal to half of Unity (round down) within 30 feet of you, using the same casting."]],"h":[["p","The Hit Points restored increase by 1d8 for each spell slot level above 1."]],"ms":["Unity"],"g":["Wardamancy"]},{"k":"kor-campward","n":"Camp Ward","l":1,"s":"Wardamancy","sa":"WAR","sp":["Abjuration","Transmutation","Enchantment"],"c":["Artificer","Cleric","Ranger","Wizard"],"bk":"kor","ct":"10 minutes or Ritual","rg":"30 feet","cp":"V, S, M (a peg, stake or stone, which serves as the Anchor)","d":"8 hours","b":[["p","State a Goal and set the spell on an Anchor within range. A 30-foot Emanation originates from the Anchor for the duration. When a creature other than you or those you name enters the Emanation, a chime sounds in the minds of you and each counted creature in it, and any of them that is asleep wakes up."],["pb","Unity","If Unity is 3 or more, sounds made inside the Emanation can't be heard from more than 60 feet away."]],"rit":1,"ms":["Anchored","Unity"],"g":["Wardamancy"]},{"k":"kor-steadfastrank","n":"Steadfast Rank","l":2,"s":"Wardamancy","sa":"WAR","sp":["Abjuration","Transmutation","Enchantment"],"c":["Artificer","Cleric","Paladin","Wizard"],"bk":"kor","ct":"Action","rg":"30 feet","cp":"V, S, M (a shield or plate, which serves as the Anchor)","d":"Concentration, up to 1 minute","b":[["p","State a Goal and set the spell on an Anchor within range. A 15-foot Emanation originates from the Anchor for the duration. At the start of each of its turns, a counted creature in the Emanation gains Temporary Hit Points equal to a third of Unity (round down) and has Advantage on saving throws against the Frightened condition until the start of its next turn."]],"h":[["p","The Emanation's radius increases by 5 feet for each spell slot level above 2. With a level 4 or higher slot, the Temporary Hit Points equal half of Unity (round down)."]],"con":1,"ms":["Anchored","Unity"],"g":["Wardamancy"]},{"k":"kor-hardenededge","n":"Hardened Edge","l":2,"s":"Wardamancy","sa":"WAR","sp":["Abjuration","Transmutation","Enchantment"],"c":["Artificer","Cleric","Paladin","Wizard"],"bk":"kor","ct":"Action","rg":"30 feet","cp":"V, S, M (a whetstone or an armourer's mark, which serves as the Anchor)","d":"Concentration, up to 1 minute","b":[["p","State a Goal and set the spell on an Anchor within range. A 10-foot Emanation originates from the Anchor for the duration. Nonmagical weapons wielded by counted creatures in the Emanation count as magical."],["pb","Unity","If Unity is 4 or more, those creatures also have a +1 bonus to attack rolls with those weapons."]],"h":[["p","With a level 4 or higher slot, the +1 bonus also applies to damage rolls."]],"con":1,"ms":["Anchored","Unity"],"g":["Wardamancy"]},{"k":"kor-forcedmarch","n":"Forced March","l":2,"s":"Wardamancy","sa":"WAR","sp":["Abjuration","Transmutation","Enchantment"],"c":["Artificer","Bard","Cleric","Ranger","Wizard"],"bk":"kor","ct":"10 minutes or Ritual","rg":"Self (30-foot Emanation)","cp":"V, S, M (a pair of boot nails)","d":"8 hours","b":[["p","State a Goal, such as \"Reach the ford by dark.\" For the duration, counted creatures in the Emanation when you cast the spell ignore Difficult Terrain made of snow, mud or slush while traveling, and have Advantage on Constitution saving throws made to avoid Exhaustion from a forced march."],["pb","Unity","If Unity is 4 or more, each of those creatures automatically succeeds on its first two such saving throws."]],"rit":1,"ms":["Unity"],"g":["Wardamancy"]},{"k":"kor-sharedburden","n":"Shared Burden","l":2,"s":"Wardamancy","sa":"WAR","sp":["Abjuration","Transmutation","Enchantment"],"c":["Artificer","Cleric","Paladin","Wizard"],"bk":"kor","ct":"Reaction, which you take when a counted creature within 30 feet of you is hit by an attack or fails a saving throw against damage","rg":"30 feet","cp":"V, S","d":"Instantaneous","b":[["p","State a Goal if you have none. The damage is divided as evenly as possible among up to Unity counted creatures within 30 feet of the target, the target included. Each share keeps the damage's type, and a creature's Resistance, Immunity or Vulnerability applies to its own share."]],"h":[["p","The damage is reduced by 1d6 before it is divided, for each spell slot level above 2."]],"ms":["Unity"],"g":["Wardamancy"]},{"k":"kor-holdyournerve","n":"Hold Your Nerve","l":2,"s":"Wardamancy","sa":"WAR","sp":["Abjuration","Transmutation","Enchantment"],"c":["Bard","Cleric","Paladin","Wizard"],"bk":"kor","ct":"Reaction, which you take when a counted creature within 60 feet of you fails a saving throw against the Charmed, Frightened or Stunned condition","rg":"60 feet","cp":"V","d":"Instantaneous","b":[["p","State a Goal if you have none. The creature succeeds on the saving throw instead."],["pb","Unity","If Unity is 4 or more, each other counted creature within 60 feet of you that is affected by the same effect also ends it."]],"h":[["p","With a level 4 or higher slot, the spell also works against the Paralyzed condition."]],"ms":["Unity"],"g":["Wardamancy"]},{"k":"kor-closedranks","n":"Closed Ranks","l":3,"s":"Wardamancy","sa":"WAR","sp":["Abjuration","Transmutation","Enchantment"],"c":["Artificer","Cleric","Paladin","Wizard"],"bk":"kor","ct":"Action","rg":"60 feet","cp":"V, S, M (a banner or standard, which serves as the Anchor)","d":"Concentration, up to 1 minute","b":[["p","State a Goal and set the spell on an Anchor within range. A 20-foot Emanation originates from the Anchor for the duration. A counted creature in the Emanation that is within 5 feet of another counted creature has Half Cover."],["pb","Unity","If Unity is 4 or more, the cover is Three-Quarters Cover instead."]],"h":[["p","The Emanation's radius increases by 5 feet for each spell slot level above 3."]],"con":1,"ms":["Anchored","Unity"],"g":["Wardamancy"]},{"k":"kor-hannekesunison","n":"Hanneke's Unison","l":3,"s":"Wardamancy","sa":"WAR","sp":["Abjuration","Transmutation","Enchantment"],"c":["Bard","Cleric","Paladin","Wizard"],"bk":"kor","ct":"Action","rg":"Self (30-foot Emanation)","cp":"V, S, M (a brass bell)","d":"Concentration, up to 1 minute","b":[["p","State a Goal. Counted creatures in the Emanation have a +2 bonus to attack rolls and saving throws for the duration."]],"h":[["p","The Emanation's radius increases by 10 feet for each spell slot level above 3."]],"con":1,"ms":["Unity"],"g":["Wardamancy"]},{"k":"kor-quicksteprank","n":"Quickstep Rank","l":3,"s":"Wardamancy","sa":"WAR","sp":["Abjuration","Transmutation","Enchantment"],"c":["Artificer","Bard","Ranger","Wizard"],"bk":"kor","ct":"Action","rg":"Self (30-foot Emanation)","cp":"V, S, M (a pair of boot nails)","d":"Concentration, up to 1 minute","b":[["p","State a Goal. Counted creatures in the Emanation have their Speed increased by 10 feet for the duration."],["pb","Unity","If Unity is 4 or more, a counted creature can take the Dash action as a Bonus Action."]],"h":[["p","The Speed increase is 5 feet greater for each spell slot level above 3."]],"con":1,"ms":["Unity"],"g":["Wardamancy"]},{"k":"kor-raisedbarricade","n":"Raised Barricade","l":3,"s":"Wardamancy","sa":"WAR","sp":["Abjuration","Transmutation","Enchantment"],"c":["Artificer","Cleric","Wizard"],"bk":"kor","ct":"Action","rg":"60 feet","cp":"V, S, M (a handful of nails or sand)","d":"Concentration, up to 10 minutes","b":[["p","State a Goal. A barricade of packed earth and timber rises from the ground in a straight line within range, 30 feet long, 10 feet high and 1 foot thick. It provides Three-Quarters Cover, and creatures and objects can't pass through it. Each 10-foot section has AC 15 and 30 Hit Points, and a destroyed section ends."],["pb","Unity","If Unity is 4 or more, the barricade can be up to 60 feet long."]],"h":[["p","The Hit Points of each section increase by 10 for each spell slot level above 3."]],"con":1,"ms":["Unity"],"g":["Wardamancy"]},{"k":"kor-laststand","n":"Last Stand","l":3,"s":"Wardamancy","sa":"WAR","sp":["Abjuration","Transmutation","Enchantment"],"c":["Artificer","Cleric","Paladin","Wizard"],"bk":"kor","ct":"Reaction, which you take when a counted creature within 30 feet of you is reduced to 0 Hit Points but not killed outright","rg":"30 feet","cp":"V, S","d":"Instantaneous","b":[["p","State a Goal if you have none. The creature drops to 1 Hit Point instead. Each other counted creature within 30 feet of it gains Temporary Hit Points equal to Unity."]],"h":[["p","The Temporary Hit Points increase by 2 for each spell slot level above 3."]],"ms":["Unity"],"g":["Wardamancy"]},{"k":"kor-barredgate","n":"Barred Gate","l":4,"s":"Wardamancy","sa":"WAR","sp":["Abjuration","Transmutation","Enchantment"],"c":["Artificer","Cleric","Paladin","Wizard"],"bk":"kor","ct":"Action","rg":"Touch","cp":"V, S, M (a door, gate or hatch, which serves as the Anchor)","d":"1 hour","b":[["p","State a Goal. You seal a door, gate, hatch or similar object you touch, and a 20-foot Emanation originates from it for the duration. The Anchor can't be opened by nonmagical means except by you and those you name. A creature other than those you name that tries to open or break it makes a Strength saving throw, taking 4d8 Force damage on a failed save and being pushed up to 10 feet away. The Knock spell suppresses the seal for 10 minutes."],["pb","Unity","If Unity is 6 or more, the damage is 6d8."]],"h":[["p","The damage increases by 1d8 for each spell slot level above 4."]],"ms":["Anchored","Unity"],"g":["Wardamancy"]},{"k":"kor-temperedplate","n":"Tempered Plate","l":4,"s":"Wardamancy","sa":"WAR","sp":["Abjuration","Transmutation","Enchantment"],"c":["Artificer","Cleric","Paladin","Wizard"],"bk":"kor","ct":"Action","rg":"Self (30-foot Emanation)","cp":"V, S, M (an armourer's file)","d":"Concentration, up to 10 minutes","b":[["p","State a Goal. Counted creatures in the Emanation when you cast the spell have their armor and shields tempered for the duration."],["pb","Unity","If Unity is 3 or more, those creatures have a +1 bonus to Armor Class. If Unity is 5 or more, the bonus is +2."]],"h":[["p","With a level 6 or higher slot, the duration is up to 1 hour."]],"con":1,"ms":["Unity"],"g":["Wardamancy"]},{"k":"kor-katarinsconcertedstrike","n":"Katarin's Concerted Strike","l":4,"s":"Wardamancy","sa":"WAR","sp":["Abjuration","Transmutation","Enchantment"],"c":["Bard","Cleric","Paladin","Wizard"],"bk":"kor","ct":"Action","rg":"Self (60-foot Emanation)","cp":"V, S, M (a signal whistle)","d":"Instantaneous","b":[["p","State a Goal and choose a creature you can see within the Emanation. Up to half of Unity (round up) counted creatures in the Emanation that can see the target can each use their Reaction to make one weapon attack or cast a cantrip with a casting time of 1 action against it."]],"h":[["p","One additional counted creature can respond for each spell slot level above 4."]],"ms":["Unity"],"g":["Wardamancy"]},{"k":"kor-unbrokenline","n":"Unbroken Line","l":4,"s":"Wardamancy","sa":"WAR","sp":["Abjuration","Transmutation","Enchantment"],"c":["Bard","Cleric","Paladin","Wizard"],"bk":"kor","ct":"Action","rg":"60 feet","cp":"V, S, M (a banner, which serves as the Anchor)","d":"Concentration, up to 1 minute","b":[["p","State a Goal and set the spell on an Anchor within range. A 30-foot Emanation originates from the Anchor for the duration. Counted creatures in the Emanation can't have the Frightened or Charmed condition, and any that has either ends it when you cast the spell."],["pb","Unity","If Unity is 6 or more, counted creatures also have Advantage on saving throws against the Stunned and Paralyzed conditions."]],"h":[["p","The Emanation's radius increases by 10 feet for each spell slot level above 4."]],"con":1,"ms":["Anchored","Unity"],"g":["Wardamancy"]},{"k":"kor-shapedredoubt","n":"Shaped Redoubt","l":4,"s":"Wardamancy","sa":"WAR","sp":["Abjuration","Transmutation","Enchantment"],"c":["Artificer","Cleric","Wizard"],"bk":"kor","ct":"Action","rg":"90 feet","cp":"V, S, M (a shovel or trowel)","d":"Concentration, up to 1 hour","b":[["p","State a Goal. Earth and timber rise into a ring-shaped earthwork centered on a point within range. It has a 30-foot radius, walls 10 feet high and 2 feet thick, and a 10-foot gap that you choose to serve as a gate. The walls provide Three-Quarters Cover. Each 10-foot section has AC 15 and 50 Hit Points, and a destroyed section ends."],["pb","Unity","If Unity is 6 or more, a 10-foot-wide, 10-foot-deep ditch of stakes rings the outside of the walls. It counts as Difficult Terrain, and a creature other than a counted creature takes 2d6 Piercing damage the first time it enters the ditch on a turn."]],"h":[["p","The radius increases by 10 feet for each spell slot level above 4."]],"con":1,"ms":["Unity"],"g":["Wardamancy"]},{"k":"kor-musterstrong","n":"Muster Strong","l":5,"s":"Wardamancy","sa":"WAR","sp":["Abjuration","Transmutation","Enchantment"],"c":["Bard","Cleric","Paladin","Wizard"],"bk":"kor","ct":"Action","rg":"Self (30-foot Emanation)","cp":"V, S","d":"Instantaneous","b":[["p","State a Goal. Each counted creature in the Emanation gains Temporary Hit Points equal to 2d8 + Unity and can end the Charmed or Frightened condition on itself."]],"h":[["p","The Temporary Hit Points increase by 1d8 for each spell slot level above 5."]],"ms":["Unity"],"g":["Wardamancy"]},{"k":"kor-aldemarswardline","n":"Aldemar's Ward-Line","l":5,"s":"Wardamancy","sa":"WAR","sp":["Abjuration","Transmutation","Enchantment"],"c":["Artificer","Cleric","Paladin","Wizard"],"bk":"kor","ct":"Action","rg":"120 feet","cp":"V, S, M (two stakes or poles, each of which serves as an Anchor)","d":"Concentration, up to 10 minutes","b":[["p","State a Goal and set the spell on two Anchors within range. A wall of ward-light stretches in a straight line between them, up to 120 feet long, 20 feet high and 6 inches thick. Creatures other than counted creatures can't pass through it. Attacks and spells can pass. For this spell, count creatures within 30 feet of either Anchor to determine Unity. The spell ends if either Anchor is destroyed."],["pb","Unity","If Unity is 6 or more, a creature other than a counted creature takes 4d8 Force damage the first time it touches the wall on a turn."]],"h":[["p","The wall's length increases by 30 feet for each spell slot level above 5."]],"con":1,"ms":["Anchored","Unity"],"g":["Wardamancy"]},{"k":"kor-hardenedhost","n":"Hardened Host","l":5,"s":"Wardamancy","sa":"WAR","sp":["Abjuration","Transmutation","Enchantment"],"c":["Artificer","Cleric","Paladin","Wizard"],"bk":"kor","ct":"Action","rg":"Self (60-foot Emanation)","cp":"V, S, M (a pinch of iron filings)","d":"Concentration, up to 1 minute","b":[["p","State a Goal. For the duration, counted creatures in the Emanation harden against blows."],["pb","Unity","If Unity is 3 or more, choose Bludgeoning, Piercing or Slashing when you cast the spell. Counted creatures have Resistance to that damage type from nonmagical attacks. If Unity is 5 or more, choose two of those types. If Unity is 8 or more, the Resistance applies to all three."]],"con":1,"ms":["Unity"],"g":["Wardamancy"]},{"k":"kor-concordofarms","n":"Concord of Arms","l":5,"s":"Wardamancy","sa":"WAR","sp":["Abjuration","Transmutation","Enchantment"],"c":["Bard","Cleric","Paladin","Ranger","Wizard"],"bk":"kor","ct":"Action","rg":"Self (60-foot Emanation)","cp":"V, S, M (a silver whistle)","d":"Concentration, up to 1 minute","b":[["p","State a Goal. At the end of each round, each creature in the Emanation that was hit by attacks from two or more different counted creatures that round takes 2d8 Force damage."],["pb","Unity","If Unity is 4, the damage is 3d8. If Unity is 5 or more, it is 4d8."]],"h":[["p","The damage increases by 1d8 for each spell slot level above 5."]],"con":1,"ms":["Unity"],"g":["Wardamancy"]},{"k":"kor-sharedward","n":"Shared Ward","l":5,"s":"Wardamancy","sa":"WAR","sp":["Abjuration","Transmutation","Enchantment"],"c":["Artificer","Cleric","Paladin","Wizard"],"bk":"kor","ct":"Action","rg":"60 feet","cp":"V, S, M (a shield or plate, which serves as the Anchor)","d":"Concentration, up to 10 minutes","b":[["p","State a Goal and set the spell on an Anchor within range. A 30-foot Emanation originates from the Anchor for the duration. Choose Acid, Cold, Fire, Lightning, Poison or Thunder. Counted creatures in the Emanation have Resistance to that damage type."],["pb","Unity","If Unity is 5 or more, choose a second damage type from the list."]],"h":[["p","The Emanation's radius increases by 5 feet for each spell slot level above 5."]],"con":1,"ms":["Anchored","Unity"],"g":["Wardamancy"]},{"k":"kor-dietmarswatchtower","n":"Dietmar's Watchtower","l":6,"s":"Wardamancy","sa":"WAR","sp":["Abjuration","Transmutation","Enchantment"],"c":["Artificer","Cleric","Wizard"],"bk":"kor","ct":"Action","rg":"120 feet","cp":"V, S, M (a small stone)","d":"Concentration, up to 1 hour","b":[["p","State a Goal. A stone tower rises from the ground at a point within range, 20 feet square and 40 feet high, with walls 2 feet thick, a door, arrow slits and a ladder inside. The walls provide Total Cover against attacks that don't pass through the slits. Each 10-foot section has AC 17 and 100 Hit Points, and a destroyed section ends. When the spell ends, the tower sinks into the ground. A creature in the tower's footprint when you cast the spell is moved to the nearest unoccupied space outside it, without taking damage."],["pb","Unity","If Unity is 8 or more, the tower can be up to 60 feet high and each section has 150 Hit Points."]],"h":[["p","With a level 7 or higher slot, the duration is up to 8 hours."]],"con":1,"ms":["Unity"],"g":["Wardamancy"]},{"k":"kor-interlockingwards","n":"Interlocking Wards","l":6,"s":"Wardamancy","sa":"WAR","sp":["Abjuration","Transmutation","Enchantment"],"c":["Artificer","Cleric","Paladin","Wizard"],"bk":"kor","ct":"Action","rg":"60 feet","cp":"V, S, M (a shield or plate, which serves as the Anchor)","d":"Concentration, up to 1 minute","b":[["p","State a Goal and set the spell on an Anchor within range. A 30-foot Emanation originates from the Anchor for the duration. Whenever a counted creature in the Emanation takes damage, reduce each instance of that damage by an amount equal to Unity."]],"h":[["p","The reduction increases by 2 for each spell slot level above 6."]],"con":1,"ms":["Anchored","Unity"],"g":["Wardamancy"]},{"k":"kor-overawe","n":"Overawe","l":6,"s":"Wardamancy","sa":"WAR","sp":["Abjuration","Transmutation","Enchantment"],"c":["Bard","Cleric","Paladin","Wizard"],"bk":"kor","ct":"Action","rg":"Self (60-foot Emanation)","cp":"V, S, M (a drum or horn)","d":"Concentration, up to 1 minute","b":[["p","State a Goal. Choose up to Unity creatures in the Emanation that aren't counted creatures. Each must succeed on a Wisdom saving throw or take 3d8 Psychic damage and have the Frightened condition for the duration. A Frightened creature repeats the saving throw at the end of each of its turns, ending the condition on itself on a success."]],"h":[["p","The damage increases by 1d8 for each spell slot level above 6."]],"con":1,"ms":["Unity"],"g":["Wardamancy"]},{"k":"kor-armingthehost","n":"Arming the Host","l":6,"s":"Wardamancy","sa":"WAR","sp":["Abjuration","Transmutation","Enchantment"],"c":["Artificer","Cleric","Paladin","Wizard"],"bk":"kor","ct":"1 hour","rg":"Self (30-foot Emanation)","cp":"V, S, M (a whetstone and an armourer's file worth 100 gp, which the spell consumes)","d":"8 hours","b":[["p","State a Goal. Nonmagical weapons wielded by counted creatures in the Emanation when you cast the spell count as magical for the duration."],["pb","Unity","If Unity is 4 or more, those weapons also have a +1 bonus to attack and damage rolls. If Unity is 8 or more, the bonus is +2. A weapon that already has a bonus uses the higher one."]],"h":[["p","With a level 8 or higher slot, the duration is 24 hours."]],"ms":["Unity"],"g":["Wardamancy"]},{"k":"kor-orsolyasunbrokenhost","n":"Orsolya's Unbroken Host","l":7,"s":"Wardamancy","sa":"WAR","sp":["Abjuration","Transmutation","Enchantment"],"c":["Bard","Cleric","Paladin","Wizard"],"bk":"kor","ct":"Action","rg":"Self (60-foot Emanation)","cp":"V, S, M (a drum)","d":"Concentration, up to 1 minute","b":[["p","State a Goal. Each round, a number of times equal to Unity minus 1 (minimum 1), a counted creature in the Emanation can give itself Advantage on an attack roll or saving throw it makes (no action required). The limit is shared among all counted creatures."]],"h":[["p","The Emanation's radius increases by 10 feet for each spell slot level above 7."]],"con":1,"ms":["Unity"],"g":["Wardamancy"]},{"k":"kor-closedground","n":"Closed Ground","l":7,"s":"Wardamancy","sa":"WAR","sp":["Abjuration","Transmutation","Enchantment"],"c":["Artificer","Cleric","Wizard"],"bk":"kor","ct":"Action","rg":"120 feet","cp":"V, S, M (a stake with a bell tied to it, which serves as the Anchor)","d":"Concentration, up to 10 minutes","b":[["p","State a Goal and set the spell on an Anchor within range. A 100-foot Emanation originates from the Anchor for the duration. A spell cast into or within the Emanation by a creature other than a counted creature fails if its level is equal to or lower than half of Unity (round down). The spell slot is expended."]],"h":[["p","The level of spell that fails increases by 1 for each spell slot level above 7."]],"con":1,"ms":["Anchored","Unity"],"g":["Wardamancy"]},{"k":"kor-breakingward","n":"Breaking Ward","l":7,"s":"Wardamancy","sa":"WAR","sp":["Abjuration","Transmutation","Enchantment"],"c":["Artificer","Cleric","Wizard"],"bk":"kor","ct":"Action","rg":"Touch","cp":"V, S, M (a pair of iron wedges worth 200 gp, which the spell consumes)","d":"24 hours or until triggered","b":[["p","State a Goal and set the spell on an Anchor you touch. The ward is hidden. A creature can find it with a Study action (Intelligence (Arcana) check against your spell save DC). The first time a creature other than you, those you name or a counted creature enters a 30-foot Emanation originating from the Anchor, the ward discharges. Each such creature in the Emanation makes a Strength saving throw, taking 13d8 Force damage on a failed save or half as much damage on a successful one."],["pb","Unity","If Unity is 8 or more, the damage is 15d8. If Unity is 10 or more, it is 17d8."]],"h":[["p","The damage increases by 1d8 for each spell slot level above 7."]],"ms":["Anchored","Unity"],"g":["Wardamancy"]},{"k":"kor-whettedhost","n":"Whetted Host","l":7,"s":"Wardamancy","sa":"WAR","sp":["Abjuration","Transmutation","Enchantment"],"c":["Artificer","Cleric","Paladin","Ranger","Wizard"],"bk":"kor","ct":"Action","rg":"Self (60-foot Emanation)","cp":"V, S, M (a whetstone)","d":"Concentration, up to 1 minute","b":[["p","State a Goal. Once on each of its turns, when a counted creature in the Emanation hits with a weapon attack, it deals extra damage equal to Unity (maximum 6). The damage is of the weapon's type."]],"h":[["p","The Emanation's radius increases by 10 feet for each spell slot level above 7."]],"con":1,"ms":["Unity"],"g":["Wardamancy"]},{"k":"kor-wolmarsfortressrising","n":"Wolmar's Fortress Rising","l":8,"s":"Wardamancy","sa":"WAR","sp":["Abjuration","Transmutation","Enchantment"],"c":["Artificer","Cleric","Wizard"],"bk":"kor","ct":"Action","rg":"300 feet","cp":"V, S, M (a handful of stones worth 500 gp, which the spell consumes)","d":"24 hours","b":[["p","State a Goal. On open ground, a stone fortress rises centered on a point within range. It is 120 feet square, with walls 30 feet high and 5 feet thick, towers at each corner 50 feet high, and a gatehouse with a portcullis. Each 10-foot section has AC 17 and 200 Hit Points. A creature in the footprint of a wall makes a Dexterity saving throw, and on a failure it is moved to the nearest unoccupied space without taking damage. When the spell ends, the fortress crumbles into rubble."],["pb","Unity","If Unity is 8 or more, each section has 300 Hit Points. If Unity is 10 or more, an inner keep 40 feet square and 60 feet high also rises in the courtyard."]],"ms":["Unity"],"g":["Wardamancy"]},{"k":"kor-ingrathsindomitablehost","n":"Ingrath's Indomitable Host","l":8,"s":"Wardamancy","sa":"WAR","sp":["Abjuration","Transmutation","Enchantment"],"c":["Bard","Cleric","Paladin","Wizard"],"bk":"kor","ct":"Action","rg":"Self (60-foot Emanation)","cp":"V, S, M (a tarnished medal)","d":"Concentration, up to 1 minute","b":[["p","State a Goal. Counted creatures in the Emanation can't have the Frightened, Charmed or Stunned condition, and any that has one ends it when you cast the spell. At the start of each of its turns, a counted creature in the Emanation regains Hit Points equal to Unity + 5."]],"h":[["p","With a level 9 slot, the Emanation's radius is 120 feet."]],"con":1,"ms":["Unity"],"g":["Wardamancy"]},{"k":"kor-standasone","n":"Stand as One","l":8,"s":"Wardamancy","sa":"WAR","sp":["Abjuration","Transmutation","Enchantment"],"c":["Cleric","Paladin","Wizard"],"bk":"kor","ct":"Reaction, which you take when a counted creature within 60 feet of you fails a saving throw against a spell or other magical effect","rg":"60 feet","cp":"V","d":"Instantaneous","b":[["p","State a Goal if you have none. The creature succeeds on the saving throw instead. In addition, up to half of Unity (round down) other counted creatures within 60 feet of you have Advantage on saving throws until the end of your next turn."]],"ms":["Unity"],"g":["Wardamancy"]},{"k":"kor-ironcladmuster","n":"Ironclad Muster","l":8,"s":"Wardamancy","sa":"WAR","sp":["Abjuration","Transmutation","Enchantment"],"c":["Artificer","Cleric","Paladin","Wizard"],"bk":"kor","ct":"Action","rg":"Self (60-foot Emanation)","cp":"V, S, M (iron filings and a drop of oil)","d":"Concentration, up to 1 minute","b":[["p","State a Goal. For the duration, counted creatures in the Emanation are armored in ward-light."],["pb","Unity","If Unity is 3 or more, they have Resistance to Bludgeoning, Piercing and Slashing damage from nonmagical attacks. If Unity is 5 or more, the Resistance applies to that damage from all sources. If Unity is 8 or more, they also have Resistance to one other damage type of your choice."]],"con":1,"ms":["Unity"],"g":["Wardamancy"]},{"k":"kor-standardofthehost","n":"Standard of the Host","l":9,"s":"Wardamancy","sa":"WAR","sp":["Abjuration","Transmutation","Enchantment"],"c":["Bard","Cleric","Paladin","Wizard"],"bk":"kor","ct":"Action","rg":"60 feet","cp":"V, S, M (a banner, which serves as the Anchor)","d":"Concentration, up to 1 minute","b":[["p","State a Goal and set the spell on an Anchor within range. A 60-foot Emanation originates from the Anchor for the duration. Whenever a counted creature in the Emanation makes an attack roll, a saving throw or an ability check, it gains a bonus to the roll equal to a quarter of Unity (round down, minimum 1)."]],"con":1,"ms":["Anchored","Unity"],"g":["Wardamancy"]},{"k":"kor-theunbreached","n":"The Unbreached","l":9,"s":"Wardamancy","sa":"WAR","sp":["Abjuration","Transmutation","Enchantment"],"c":["Artificer","Cleric","Wizard"],"bk":"kor","ct":"1 hour","rg":"Touch","cp":"V, S, M (a keystone worth 5,000 gp, which the spell consumes and which serves as the Anchor)","d":"7 days","b":[["p","State a Goal. You set a keystone in a fortress, hall or tower, and a 200-foot Emanation originates from it for the duration. Structures in the Emanation have Immunity to damage from nonmagical sources. A creature other than a counted creature makes a Wisdom saving throw when it tries to enter the Emanation, and on a failed save it can't enter. A creature already inside when you cast the spell makes the same saving throw at the start of its turn, and on a failed save it is moved to the nearest unoccupied space outside."],["pb","Unity","If Unity is 10 or more, the structures also have Resistance to damage from spells and magical attacks."]],"ms":["Anchored","Unity"],"g":["Wardamancy"]},{"k":"kor-vessnasgrandassault","n":"Vessna's Grand Assault","l":9,"s":"Wardamancy","sa":"WAR","sp":["Abjuration","Transmutation","Enchantment"],"c":["Cleric","Paladin","Bard","Wizard"],"bk":"kor","ct":"Action","rg":"Self (120-foot Emanation)","cp":"V, S, M (a signal horn)","d":"Instantaneous","b":[["p","State a Goal. Up to Unity counted creatures in the Emanation can each use their Reaction to move up to their Speed without provoking Opportunity Attacks and make one weapon attack or cast a cantrip with a casting time of 1 action against a creature of its choice. A weapon attack that hits deals an extra 2d8 damage of the attack's type."]],"ms":["Unity"],"g":["Wardamancy"]}];
  S.forEach(function (s) { D.spells.push(s); });
})();
